/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
'use strict';
const D=globalThis.RA.D;
const Q=(prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({prompt,answer,options:[answer,wrong1,wrong2],explain,errorType});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>{const senseMap={Medicare:[1,2,2,1],medication:[1,2,1,1],medicine:[1,2,3,1],medieval:[1,2,1,1],meditative:[1,2,1,1],Mediterranean:[1,2,1,1],medium:[1,2,2,1],meek:[1,2,1,1],meet:[1,2,3,4],meeting:[1,1,2,1],melancholy:[1,2,1,2],mellow:[1,2,2,1],melodious:[1,2,1,1],melody:[1,2,1,1],melt:[1,2,1,2],melting:[1,2,1,1],member:[1,2,1,1],membership:[1,2,1,1],meme:[1,2,1,2],memorandum:[1,2,1,2],memorial:[1,2,1,2],memory:[1,2,3,2],menace:[1,2,3,3],mend:[1,2,1,2],menial:[1,2,1,2],mental:[1,2,2,1],mention:[1,2,1,1],mentor:[1,2,1,2],menu:[1,2,2,2],mercantile:[1,2,1,1],mercenary:[1,2,2,2],merchandise:[1,2,1,2],merchant:[1,2,1,2],mercury:[1,2,2,1],mercy:[1,2,1,1],mere:[1,2,2,2],merge:[1,2,1,1],merit:[1,2,2,1]};return D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((q,i)=>({...q,id:w+'.q'+(i+1),senseId:w+'.s'+(senseMap[w]?.[i]||1),type:'辨义与用法'}))});};
P('medical science','Medical science combines medical and science and refers to the systematic study of preventing, diagnosing, and treating illness.',C('medical science.s1','健康研究','Medical science has improved survival by developing safer vaccines and treatments for infections that once proved fatal.','医学通过开发更安全的疫苗和疗法，提高了人们的生存率；过去一些感染曾会致命。','Medical science has improved survival / by developing safer vaccines and treatments / for infections / that once proved fatal.','medical science 作学科名词，指系统研究疾病预防、诊断和治疗的领域。','疫苗与疗法研究属于医学科学。'),M('The course called the study of weather patterns medical science, although it covered no health or illness.','The course called the study of disease prevention and treatment medical science.','研究天气而非健康疾病，不属于医学科学。'),[Q('Medical science studies?','health, illness, prevention, and treatment','the design of marketplaces','marble sculpture only','medical science 指研究健康与疾病的科学。'),Q('What helped improve survival in the example?','safer vaccines and treatments','higher margins on medicine','more medieval manuscripts','疫苗和疗法降低疾病危害。'),Q('Medical science is a?','field of systematic study','single medicine dose','type of meeting','它是一个科学研究领域。'),Q('Which activity belongs to medical science?','testing a treatment for infection','mapping a ship’s mast','training a meerkat','治疗感染的研究属于医学科学。')]);
P('Medicare','Medicare is a blended name built from medical and care; it is the US federal health-insurance programme chiefly associated with older people.',[C('Medicare.s1','医疗保障','The hospital billing office helped Ruth check which outpatient services her Medicare plan would cover.','医院结算处帮助露丝确认她的 Medicare 计划会承保哪些门诊服务。','The hospital billing office helped Ruth check / which outpatient services / her Medicare plan would cover.','Medicare 是美国联邦医疗保险项目的专名，注意首字母大写。','例句询问该项目下的医疗费用保障，符合 s1。'),C('Medicare.s2','保险待遇','The letter explained her Medicare coverage and listed the payments available for the approved treatment.','信件说明了她的 Medicare 保险待遇，并列出获批治疗可享有的支付项目。','The letter explained / her Medicare coverage / and listed the payments / available for the approved treatment.','Medicare 也可指该制度提供的保险保障和支付待遇。','信件讲具体承保与支付，符合 s2。')],M('The brochure called private holiday insurance Medicare, although it was not part of the US federal programme.','The brochure identified Medicare as the US federal health-insurance programme and described its coverage separately from private travel insurance.','私人旅行保险不能与美国联邦 Medicare 项目混为一谈。'),[Q('Medicare is a US federal?','health-insurance programme','maritime safety law','university degree','Medicare 是美国联邦医疗保险项目。'),Q('What did Ruth check?','whether outpatient services were covered','whether the hospital had a meeting room','whether her medicine was medieval','她核查门诊服务是否在保障范围内。'),Q('Medicare coverage refers to?','benefits and payments under the programme','the medical science textbook only','a doctor’s personal income','该词也可指 Medicare 提供的承保待遇。'),Q('Which spelling is correct for the programme name?','Medicare','medicare','MediCareful','项目专名按 Medicare 拼写。','capitalization')]);
P('medicate','Medicate comes from Latin medicare, “to heal or treat,” and means to treat someone with medicine or drugs.',C('medicate.s1','临床治疗','The doctor decided to medicate the patient only after reviewing her symptoms, allergies, and test results.','医生先查看患者的症状、过敏史和检查结果，然后才决定给她用药。','The doctor decided / to medicate the patient / only after reviewing / her symptoms, allergies, and test results.','medicate 作及物动词，后接接受药物治疗的人。','医生评估后使用药物治疗，符合 s1。'),M('The clinic medicated the patient by refusing all drugs and providing no treatment.','The clinic medicated the patient with a prescribed drug after reviewing the test results.','拒绝用药不是用药物治疗。'),[Q('To medicate a patient is to?','treat the patient with medicine','write a map for the patient','arrange a meeting','medicate 表示给患者用药治疗。'),Q('What did the doctor review first?','symptoms, allergies, and test results','the patient’s marketplace','a medieval calendar','医生在用药前评估病情与过敏史。'),Q('Which verb is closest to medicate?','treat with drugs','marry','masticate','medicate 的意思是用药物治疗。'),Q('Which construction is natural?','medicate a patient with a drug','medicate a patient at a map','medicate a symptom into a meeting','常用结构是 medicate someone with something。','collocation')]);
P('medication','Medication comes from medicate plus -ion and means a drug used for treatment or the treatment given with such drugs.',[C('medication.s1','处方用药','Keep the medication in its labelled container and follow the pharmacist’s instructions about when to take it.','请把药物保存在贴有标签的容器里，并按药剂师的说明服用。','Keep the medication / in its labelled container / and follow the pharmacist’s instructions / about when to take it.','medication 作名词可指具体药物，常用 take medication。','有标签并按说明服用的是药剂。'),C('medication.s2','治疗方案','The patient’s medication lasted six weeks and combined several prescribed drugs under medical supervision.','患者的药物治疗持续了六周，在医疗监督下结合了几种处方药。','The patient’s medication lasted six weeks / and combined several prescribed drugs / under medical supervision.','medication 也可指以药物进行的整体治疗。','持续多周的药物方案符合 s2。')],M('The pharmacist gave her a medication, meaning a decorative glass marble with no medical use.','The pharmacist gave her a medication, a drug prescribed to treat her condition.','装饰弹珠不是药物。'),[Q('A medication can be?','a drug used to treat illness','a map of the hospital','a piece of medical equipment only','medication 可指治疗疾病的药物。'),Q('A patient’s medication may also mean?','the drug-based treatment plan','the patient’s marital status','a single medical meeting','medication 也可指整体药物治疗。'),Q('What should the patient follow?','the pharmacist’s instructions','the manuscript margin','the Mediterranean tide','药剂师说明了如何服药。'),Q('Which phrase is natural?','take medication as directed','medication a patient with a map','a medication of illness','常说按指示服用 medication。','collocation')]);
P('medicinal','Medicinal comes from Latin medicinalis, “healing,” and describes something used to treat illness or related to medicine.',C('medicinal.s1','植物用途','The herbalist explained that the plant has a medicinal use but warned visitors not to ingest it without expert advice.','草药师说明这种植物有药用价值，但提醒访客未经专家建议不要服用。','The herbalist explained / that the plant has a medicinal use / but warned visitors / not to ingest it without expert advice.','medicinal 作形容词，修饰 use，表示有治疗用途。','植物被说明有药用价值。'),M('The guide called the poisonous plant medicinal because it had no possible use in treating disease.','The guide described the plant as medicinal because it has a recognised use in treatment.','完全没有治疗用途不支持 medicinal 的说法。'),[Q('A medicinal plant is one that?','has a use in treating illness','is designed for a meeting','grows only in a medieval city','medicinal 表示有药用价值。'),Q('What warning did the herbalist give?','do not ingest it without expert advice','take any amount immediately','use it to mark a map','草药师建议未经专家意见不要服用。'),Q('Which phrase is natural?','medicinal properties','medicinally plant','medicine propertiesful','medicinal 作形容词修饰 properties。','grammar'),Q('Medicinal is related to?','medicine','marble','meek','该词与 medicine 同源相关。')]);
P('medicine','Medicine came through Old French from Latin medicina; it can mean a drug, the science and practice of health care, or treatment by drugs rather than surgery.',[C('medicine.s1','家庭用药','The pharmacist reminded Leo to take the medicine with water and not to exceed the dose on the label.','药剂师提醒利奥用水服药，不要超过标签上的剂量。','The pharmacist reminded Leo / to take the medicine with water / and not to exceed / the dose on the label.','medicine 作名词可指治疗疾病的药物，take medicine 是常见表达。','标签说明药物剂量与服用方法。'),C('medicine.s2','大学专业','She studied medicine at university and later specialised in infectious diseases.','她在大学学习医学，之后专攻传染病。','She studied medicine / at university / and later specialised / in infectious diseases.','medicine 作不可数名词也指医学学科与临床实践。','大学专业及疾病专科均属医学领域。'),C('medicine.s3','内科治疗','The consultant recommended medicine rather than surgery because the condition responded well to drugs.','由于病情对药物反应良好，顾问医生建议采用内科治疗而非手术。','The consultant recommended medicine / rather than surgery / because the condition / responded well to drugs.','medicine 可特指以内科药物治疗而非外科手术。','建议用药、不做手术，符合 s3。')],M('She studied medicine at university, meaning she trained to repair ships and design their masts.','She studied medicine at university, learning how to prevent and treat illness.','船舶设计不是医学专业。'),[Q('The medicine Leo took was?','a drug to treat an illness','a medical-school course','a surgical operation','medicine 可指具体药物。'),Q('To study medicine at university is to study?','the science and practice of health care','marketing and maritime law','map-making','medicine 也指医学学科。'),Q('Medicine rather than surgery means treatment?','with drugs instead of an operation','with a map instead of a chart','with a meeting rather than a meal','medicine 可特指非手术的药物治疗。'),Q('What did the pharmacist say about the dose?','do not exceed the label amount','double it without asking','replace it with a marble','药剂师提醒不要超过标签剂量。')]);
P('medieval','Medieval comes from Medieval Latin medium aevum (“Middle Ages”) and describes that historical period or, negatively, something intolerably old-fashioned.',[C('medieval.s1','历史建筑','The museum’s medieval hall dates from the thirteenth century and still has its original stone arches.','博物馆的中世纪大厅建于十三世纪，至今仍保留原有石拱。','The museum’s medieval hall / dates from the thirteenth century / and still has / its original stone arches.','medieval 作形容词，描述欧洲约公元500至1500年的中世纪时期。','十三世纪建筑属于中世纪。'),C('medieval.s2','制度批评','The columnist called the rule medieval because it denied workers basic protections that modern law guarantees.','专栏作者称这条规定落后得像中世纪，因为它剥夺了现代法律保障工人的基本保护。','The columnist called the rule medieval / because it denied workers / basic protections / that modern law guarantees.','比喻义 medieval 带贬义，指陈旧且不可接受。','作者批评规则不合现代标准，符合 s2。')],M('The historian described the thirteenth-century hall as medieval even though it was built in 2024.','The historian described the thirteenth-century hall as medieval because it dates from the Middle Ages.','2024年新建的建筑不属于历史上的中世纪。'),[Q('A medieval hall belongs to?','the Middle Ages','the modern space age','a medical treatment','medieval 描述中世纪时期。'),Q('Calling a rule medieval may mean it is?','unacceptably old-fashioned','historically from the thirteenth century for certain','a medication','比喻义常批评某事极其陈旧。'),Q('What feature remained in the museum hall?','its original stone arches','a new Medicare card','a lunar calendar','大厅保留了原有石拱。'),Q('Medieval literally refers to an age in the?','middle','future','sea','medium aevum 意为中间时代。')]);
P('mediocre','Mediocre comes from Latin mediocris, “moderate or middling,” and describes quality that is only average or below what is expected.',C('mediocre.s1','作品评论','The film was visually polished, but its predictable plot and flat dialogue made it mediocre overall.','这部电影画面制作精良，但情节可预测、对白平淡，整体水平只能算平庸。','The film was visually polished / but its predictable plot and flat dialogue / made it mediocre / overall.','mediocre 作形容词评价质量一般或不够好，通常带负面意味。','优点不足以弥补剧情和对白平淡，符合 s1。'),M('The reviewers called the performance mediocre even though it was universally praised as extraordinary and flawless.','The reviewers called the performance mediocre because it was merely average and often uninspired.','被普遍称为非凡完美的表现不应评为平庸。'),[Q('A mediocre film is?','only average or somewhat poor','the finest work ever made','a film about a medical dose','mediocre 表示平庸、质量一般。'),Q('What weakened the film in the example?','a predictable plot and flat dialogue','a medieval stone arch','a clear meeting agenda','剧情可预测且对白平淡，使电影表现平庸。'),Q('Which word is closest to mediocre?','uninspired','matchless','marvellous','uninspired 可形容缺少出色表现。'),Q('Mediocre often expresses?','mild or clear disapproval of quality','a guarantee of excellence','a medical diagnosis','该词评价质量时常带负面意味。','register')]);
P('meditate','Meditate comes from Latin meditari (“to think over or practise”) and means to think deeply and calmly, often as a regular practice.',C('meditate.s1','专注练习','Before the difficult interview, Arun sat quietly for ten minutes to meditate and settle his thoughts.','艰难的面试前，阿伦静坐冥想了十分钟，让自己的思绪平静下来。','Before the difficult interview / Arun sat quietly / for ten minutes to meditate / and settle his thoughts.','meditate 作不及物动词，可接 on/upon a topic；此处指安静冥想。','静坐让思绪平静，符合 s1。'),M('Arun meditated by filling the room with noise and refusing to pause or reflect.','Arun meditated by sitting quietly and focusing his attention on his breathing.','不间断制造噪音与安静专注相反。'),[Q('To meditate is to?','think deeply and calmly','masticate food','meet a crowd','meditate 表示冥想或沉思。'),Q('Why did Arun meditate before the interview?','to settle his thoughts','to raise his voice','to memorise the marketplace','他想让思绪平静下来。'),Q('Which preposition can follow meditate for a topic?','on','under of','against with','常说 meditate on a question。','collocation'),Q('What did Arun do for ten minutes?','sat quietly and meditated','drove to a megacity','took an extra dose','例句写他安静坐着冥想。')]);
P('meditation','Meditation comes from Latin meditatio and names the practice of silent, focused thought or contemplation.',C('meditation.s1','健康休息','A short meditation helped the nurse regain focus after a demanding shift in the emergency ward.','急诊病房忙碌一班后，短暂冥想帮助护士重新集中注意力。','A short meditation / helped the nurse regain focus / after a demanding shift / in the emergency ward.','meditation 作不可数或可数名词，指冥想这种专注静思练习。','短暂静思帮助恢复专注。'),M('The nurse called the loud argument in the corridor a meditation, although nobody was quiet or reflective.','The nurse practised meditation in a quiet room to focus her thoughts.','嘈杂争吵不符合安静专注的冥想练习。'),[Q('Meditation is a practice of?','silent, focused thought','public marketing','mass production','meditation 指安静专注地思考。'),Q('What benefit did the nurse experience?','she regained focus','she obtained a master’s degree','she met the mayor','短暂冥想帮助护士重新集中注意力。'),Q('Which verb commonly goes with meditation?','practise','masticate','maroon','常说 practise meditation。','collocation'),Q('When did the nurse meditate?','after a demanding emergency-ward shift','during a medieval battle','before a marathon race only','她在忙碌值班后短暂冥想。')]);
P('meditative','Meditative is formed from meditate plus -ive and describes quiet, deep thought or a practice related to meditation.',[C('meditative.s1','写作风格','The essay takes a meditative tone, pausing over small details instead of rushing toward a conclusion.','这篇文章语气沉思，细看微小细节，而不是急于得出结论。','The essay takes / a meditative tone / pausing over small details / instead of rushing toward a conclusion.','meditative 作形容词可描写深沉、安静思考的状态或文风。','作者缓慢思索细节，符合 s1。'),C('meditative.s2','放松活动','The studio offers meditative breathing sessions for people who want to practise quiet concentration.','这间工作室为想练习安静专注的人提供冥想呼吸课程。','The studio offers / meditative breathing sessions / for people / who want to practise quiet concentration.','meditative 也可表示与冥想练习有关。','课程训练专注呼吸，符合 s2。')],M('The article had a meditative tone because it rushed through every idea without reflection or pause.','The article had a meditative tone because it considered each idea slowly and thoughtfully.','匆忙略过观点不符合沉思的语气。'),[Q('A meditative tone is?','quiet and reflective','loud and argumentative','purely numerical','meditative 可表示沉静深思的。'),Q('A meditative breathing session relates to?','the practice of meditation','the sale of medicine','a city meeting','meditative 也可指与冥想练习有关。'),Q('What did the essay do with small details?','paused over them thoughtfully','ignored them all','turned them into a map','文章花时间思考细节。'),Q('Which word is formed by adding -ive to meditate?','meditative','meditation','medicate','meditate + -ive 构成 meditative。','word-formation')]);
P('Mediterranean','Mediterranean comes from Latin mediterraneus (“in the middle of land”), from medius and terra; it names the sea and describes its region or peoples.',[C('Mediterranean.s1','地理位置','The Mediterranean lies between southern Europe and North Africa and connects with the Atlantic through the Strait of Gibraltar.','地中海位于南欧和北非之间，并通过直布罗陀海峡与大西洋相连。','The Mediterranean lies / between southern Europe and North Africa / and connects with the Atlantic / through the Strait of Gibraltar.','Mediterranean 作专有名词指地中海，首字母大写。','海域的位置符合 s1。'),C('Mediterranean.s2','沿岸生活','Mediterranean towns often have dry summers and mild winters influenced by the nearby sea.','地中海沿岸城镇的夏季通常干燥，冬季温和，气候受到附近海洋影响。','Mediterranean towns often have / dry summers and mild winters / influenced by / the nearby sea.','Mediterranean 作形容词，表示地中海区域或其民族、文化相关。','沿海气候受到地中海影响，符合 s2。')],M('The Mediterranean is a landlocked lake between Canada and Alaska.','The Mediterranean is the sea between southern Europe and North Africa.','地中海不是北美洲的内陆湖。'),[Q('The Mediterranean lies between?','southern Europe and North Africa','Australia and Antarctica','Asia and the Moon','地中海位于南欧与北非之间。'),Q('A Mediterranean climate is influenced by?','the nearby sea','a medieval manuscript','a medical meeting','沿海气候受地中海影响。'),Q('What connects it with the Atlantic?','the Strait of Gibraltar','the Strait of Medicare','a marshland road','直布罗陀海峡连接地中海和大西洋。'),Q('Mediterranean comes from Latin elements meaning?','middle of the land','great mountain','calm thought','mediterraneus 源于“陆地中间”的构词。')]);
P('medium','Medium comes from Latin medium (“middle”); it can mean a means of communication or a middle size, amount, or degree.',[C('medium.s1','传播渠道','Radio remains a useful medium for emergency announcements in areas where mobile service is unreliable.','在移动通信不稳定的地区，广播仍是发布紧急公告的有效媒介。','Radio remains / a useful medium / for emergency announcements / in areas where mobile service is unreliable.','medium 作可数名词，指传播信息或实现某事的媒介。','广播承担信息传播功能，符合 s1。'),C('medium.s2','衣物尺码','The shop had the jacket in small, medium, and large, and Mei chose the middle size.','商店有小、中、大三种尺码，梅选了中号夹克。','The shop had the jacket / in small, medium, and large / and Mei chose / the middle size.','medium 作形容词或名词表示中等尺寸、数量或程度。','中号处于小号和大号之间，符合 s2。')],M('Radio was called a medium for announcements even though it could not transmit sound or information.','Radio was called a medium for announcements because it carries information to listeners.','不能传递声音信息的设备不能称为传播媒介。'),[Q('Radio is a medium because it?','carries information to listeners','is the largest possible size','is a type of meditation','medium 名词义指传播信息的媒介。'),Q('A medium jacket is?','the middle size','smaller than the smallest','larger than every size','medium 表示中号。'),Q('Which list shows the usual size sequence?','small, medium, large','medium, small, largest','large, medium, tiny','medium 处于 small 和 large 之间。'),Q('Which can be a medium of communication?','radio','marrow','a mast','广播是信息传播媒介。')]);
P('meek','Meek is an old English adjective of uncertain deeper origin; it describes someone gentle and submissive, or humble and patient in a religious sense.',[C('meek.s1','人际冲突','Although the clerk was meek in manner, she calmly explained that the customer’s request broke the store’s policy.','尽管店员态度温和，她仍平静地解释顾客的要求违反了商店规定。','Although the clerk was meek in manner / she calmly explained / that the customer’s request / broke the store’s policy.','meek 可表示温顺、柔和，但不必然意味着缺乏判断或能力。','她态度温和同时坚持规则，体现温顺义。'),C('meek.s2','宗教语境','The sermon praised the meek for remaining humble and patient through hardship.','布道赞扬了那些在困境中仍保持谦卑和耐心的人。','The sermon praised the meek / for remaining humble and patient / through hardship.','宗教或圣经语境中，the meek 指谦卑忍耐的人。','困境中保持谦卑耐心，符合 s2。')],M('The supervisor called the clerk meek because she shouted at every visitor and refused to listen.','The supervisor called the clerk meek because she remained gentle and patient while explaining the rules.','对访客大吼与温和顺从相矛盾。'),[Q('A meek person is usually?','gentle and willing to yield','aggressive and domineering','a medium communication channel','meek 常指温顺、柔和。'),Q('In a religious sermon, the meek are described as?','humble and patient in hardship','expert mapmakers','people with a master’s degree','宗教义强调谦卑忍耐。'),Q('Did the clerk give up her judgement?','No; she was gentle but still explained the policy.','Yes; meek always means unable to think.','She left the marketplace.','温和并不等于没有判断力。'),Q('Which behaviour is meek?','calmly listening and responding without aggression','shouting over everyone','refusing every conversation','平静、不具攻击性的回应符合 meek。')]);
P('meerkat','Meerkat is borrowed through Afrikaans and Dutch; it is the common name of the social mongoose Suricata suricatta, native to southern Africa.',C('meerkat.s1','野生动物观察','A meerkat stood upright beside its burrow while the rest of the group searched the dry ground for insects.','一只细尾獴直立站在洞穴旁，群体其他成员则在干燥地面寻找昆虫。','A meerkat stood upright / beside its burrow / while the rest of the group / searched the dry ground for insects.','meerkat 作可数名词，指群居的非洲猫鼬。','洞穴旁警戒、群体觅食符合其行为特点。'),M('The guide identified the meerkat as a solitary ocean fish that lives below the Mediterranean.','The guide identified the meerkat as a social mongoose that lives in southern Africa.','meerkat 是非洲陆生哺乳动物，不是海鱼。'),[Q('A meerkat is a kind of?','mongoose','marlin','maple tree','细尾獴是一种猫鼬。'),Q('Where did the meerkat stand?','beside its burrow','on a ship’s mast','in a medical meeting','它站在洞穴旁。'),Q('What did the rest of its group do?','searched for insects','built a marble statue','measured a medium','群体其他成员在觅食。'),Q('Meerkats are native to?','southern Africa','the Mediterranean Sea','medieval Europe','细尾獴原生于非洲南部。')]);
P('meet','Meet comes from Old English metan (“come upon”); it means encounter someone, gather, satisfy a requirement, or a sports competition.',[C('meet.s1','初次相识','I first met Hana at a medical science conference, where we discovered that we studied similar treatments.','我第一次在医学会议上遇见哈娜，我们在那里发现彼此研究相似的疗法。','I first met Hana / at a medical science conference / where we discovered / that we studied similar treatments.','meet 作及物动词可表示遇见或结识某人。','会议上初次相识符合 s1。'),C('meet.s2','团队讨论','The research group meets every Friday to review patient data and plan the next study.','研究小组每周五开会审查患者数据并规划下一项研究。','The research group meets / every Friday / to review patient data / and plan the next study.','meet 作不及物动词表示聚会、开会。','固定时间集体讨论符合 s2。'),C('meet.s3','满足标准','The new clinic must meet strict safety standards before it can treat patients.','新诊所必须满足严格的安全标准，才能接诊患者。','The new clinic must meet / strict safety standards / before it can treat patients.','meet 可表示满足需求、条件或标准。','满足安全标准是开业条件，符合 s3。'),C('meet.s4','体育集会','The school athletics meet begins at nine, with races for students from every year group.','学校田径运动会九点开始，各年级学生都会参加比赛。','The school athletics meet begins / at nine / with races / for students from every year group.','meet 作名词可指运动会或集会。','多个年级参加的田径赛事符合 s4。')],M('The clinic meets the safety standard by failing every inspection and ignoring required repairs.','The clinic meets the safety standard by passing inspections and completing the required repairs.','检查不合格且忽视维修不符合标准。'),[Q('I met Hana at the conference means I?','encountered or got to know her there','held a sports competition with her','satisfied her medical need','meet 可表示遇见或结识。'),Q('The group meets every Friday means it?','gathers for a discussion','arrives at a standard','wins a race','meet 可表示定期聚会。'),Q('A clinic meets safety standards when it?','satisfies the required conditions','fails every inspection','has a medium-sized sign','meet 可表示符合条件。'),Q('An athletics meet is?','a sports competition or gathering','a treatment with drugs','a quiet meditation','名词 meet 可指运动会。')]);
P('meet again','Meet again combines meet and again and means to see or encounter someone another time after a period apart.',C('meet again.s1','久别重逢','After working in different cities for years, the sisters met again at their parents’ anniversary dinner.','姐妹俩多年在不同城市工作后，在父母的周年纪念晚宴上再次相见。','After working in different cities for years / the sisters met again / at their parents’ / anniversary dinner.','meet again 作动词短语，again 表示此前见过、如今重逢。','多年分开后再度见面，符合 s1。'),M('The sisters met again for the first time, although they had never met before and had no previous contact.','The sisters met again after years apart, having known each other since childhood.','从未见过的人不能称为再次相见。'),[Q('To meet again means to?','see someone another time','meet someone for the first time','satisfy a requirement','again 表示这不是第一次见面。'),Q('Where did the sisters meet again?','at their parents’ anniversary dinner','at a medieval marketplace','in a meerkat burrow','姐妹在父母周年晚宴重逢。'),Q('What happened before their reunion?','they lived in different cities for years','they had never known each other','they attended the same meeting daily','她们此前多年身处不同城市。'),Q('Which sentence uses meet again naturally?','Let’s meet again after the conference.','Let’s meet again for the first time.','Let’s meeting again yesterday.','meet again 表示之后再次见面。','grammar')]);
P('meet with','Meet with means to have an arranged meeting with someone; it can also mean to experience a reaction or event.',[C('meet with.s1','正式会见','The director will meet with the clinic staff on Monday to discuss the new medication policy.','主任将于周一会见诊所员工，讨论新的用药政策。','The director will meet with the clinic staff / on Monday / to discuss / the new medication policy.','meet with somebody 表示与某人会面，语气常较正式。','安排讨论政策的会面符合 s1。'),C('meet with.s1','遭遇反应','The proposal met with strong resistance from nurses who said the schedule was unsafe.','这项提案遭到护士们强烈反对，她们认为日程安排不安全。','The proposal met with strong resistance / from nurses / who said / the schedule was unsafe.','meet with 也可表示遭遇某种反应、评价或事件。','提案遭遇反对，符合短语的另一用法。')],M('The director met with the staff by avoiding all contact and never arranging a conversation.','The director met with the staff in a scheduled discussion about the medication policy.','没有接触或会谈不构成 meet with。'),[Q('The director will meet with staff means she will?','have an arranged meeting with them','measure their body mass','marry them','meet with 可表示正式会见。'),Q('The proposal met with resistance means it?','encountered opposition','was approved by everyone','met a sports team','meet with 可表示遭遇某种反应。'),Q('What topic was on the meeting agenda?','the medication policy','the Mediterranean climate','a meerkat burrow','会面讨论新的用药政策。'),Q('Which phrase is correct?','meet with the director','meet the director with at','meet with to the director','常用结构是 meet with someone。','collocation')]);
P('meeting','Meeting comes from meet plus -ing and names an arranged discussion or an occasion when people see one another.',[C('meeting.s1','工作讨论','The safety committee held a meeting to decide whether the clinic should replace its ageing equipment.','安全委员会召开会议，决定诊所是否应更换老旧设备。','The safety committee held a meeting / to decide / whether the clinic should replace / its ageing equipment.','meeting 作可数名词，常与 hold/attend a meeting 连用。','委员会讨论并作决定，符合 s1。'),C('meeting.s2','偶然会面','Their meeting at the station was brief, but it led to a useful exchange of research notes.','他们在车站的会面很短暂，却促成了一次有用的研究笔记交流。','Their meeting at the station / was brief / but it led to / a useful exchange of research notes.','meeting 也可指人们见面这一场合，不一定是正式会议。','车站短暂相遇并交换资料，符合 s2。')],M('The committee held a meeting by ensuring that no members gathered, spoke, or discussed anything.','The committee held a meeting in which members gathered to discuss the equipment decision.','无人聚集或讨论就没有召开会议。'),[Q('A committee meeting is?','an arranged discussion','a medicine dose','a map of the Mediterranean','meeting 可指正式讨论会议。'),Q('What was the committee deciding?','whether to replace old equipment','whether to meet a meerkat','whether to marry a clinic','会议讨论是否更换旧设备。'),Q('Their brief meeting at the station was?','an occasion when they saw one another','a weekly formal committee session','a medical treatment','meeting 也可指一次会面。'),Q('Which collocation is natural?','hold a meeting','masticate a meeting','meeting with to the staff','常说 hold a meeting。','collocation')]);
P('megacity','Megacity combines mega- (“very large”) and city and means an extremely large urban area, commonly defined by a population above ten million.',C('megacity.s1','城市人口','The megacity’s rail network carries millions of passengers each day between outer districts and the central business area.','这座特大城市的铁路网络每天在外围城区和中央商务区之间运送数百万乘客。','The megacity’s rail network carries millions of passengers / each day / between outer districts / and the central business area.','megacity 作可数名词，通常指人口超过一千万的超大型城市区域。','庞大人口和跨区交通符合 megacity 特征。'),M('The village of two hundred residents was described as a megacity because it had one bus stop.','The urban area of more than ten million residents was described as a megacity.','只有两百名居民的小村庄不属于特大城市。'),[Q('A megacity is an urban area of?','extreme size, commonly over ten million people','a few hundred residents','no permanent population','megacity 通常指人口超过一千万的超大型城市。'),Q('What did the megacity’s rail network carry?','millions of passengers each day','marrow and medicine','marsh plants only','铁路网络每天运送大量乘客。'),Q('Mega- in megacity means?','very large','very quiet','medieval','mega- 表示巨大。','word-formation'),Q('Which place is most likely a megacity?','an urban region with more than ten million residents','a hamlet of two hundred people','a single clinic building','人口千万级都市最符合 megacity。')]);
P('megafossil','Megafossil combines mega- (“large”) and fossil and names a fossil large enough to be seen without a microscope.',C('megafossil.s1','地质考察','The field team photographed a megafossil leaf impression clearly visible in the sandstone without magnification.','野外小组拍下了砂岩中一处肉眼清晰可见的巨型化石叶痕，无需放大。','The field team photographed / a megafossil leaf impression / clearly visible in the sandstone / without magnification.','megafossil 作名词，区别于必须借助显微镜观察的微体化石。','化石无需放大即可看见，符合 s1。'),M('The sample was a megafossil even though it could only be seen under a powerful microscope.','The sample was a megafossil because its fossilised structure was visible to the naked eye.','只能借助显微镜看到的属于微体化石。'),[Q('A megafossil can be seen?','with the naked eye','only with a powerful microscope','only after it melts','megafossil 指肉眼可见的化石。'),Q('What fossil impression did the team photograph?','a leaf','a meerkat','a medieval meeting','小组拍摄的是化石叶痕。'),Q('Mega- means?','large','ancient','soft','mega- 表示巨大。','word-formation'),Q('A megafossil differs from a microfossil mainly by?','its visible size','its colour only','the language used to name it','巨型化石肉眼可见，微体化石需要放大。')]);
P('megalopolis','Megalopolis comes from Greek megas (“great”) and polis (“city”); it is a vast built-up region formed by neighbouring metropolitan areas.',C('megalopolis.s1','区域规划','Rail lines and highways link the neighbouring cities into a megalopolis stretching along the coast.','铁路和公路把相邻城市连接成沿海绵延的大都市连绵带。','Rail lines and highways link / the neighbouring cities / into a megalopolis / stretching along the coast.','megalopolis 作可数名词，强调多个相邻都市连成的大型城市区域。','城市群由交通网络连接并连续扩展，符合 s1。'),M('The planner called the isolated village a megalopolis although no neighbouring city or continuous urban area existed.','The planner called the connected urban region a megalopolis because several neighbouring cities had grown together.','没有相邻城市或连续建成区的小村庄不属于 megalopolis。'),[Q('A megalopolis is?','a vast region of neighbouring cities that have grown together','a village with one street','a single medieval stone building','megalopolis 指多个都市连成的超大型城市区域。'),Q('What linked the cities in the example?','rail lines and highways','a melange of paint','a melody','交通网络把相邻城市连接起来。'),Q('The Greek element polis means?','city','sea','medicine','polis 的意思是“城市”。','word-formation'),Q('Which place is most likely a megalopolis?','a continuous built-up corridor linking several metropolitan areas','a single remote farmhouse','a small island with no town','相邻大都市连成的区域符合该词。')]);
P('megawatt','Megawatt combines mega- and watt; one megawatt equals one million watts and is used to express large power output.',C('megawatt.s1','能源报告','The wind farm can deliver up to one megawatt of power when its turbines are turning in strong winds.','风力强劲、涡轮机转动时，这座风电场最多可输出一兆瓦电力。','The wind farm can deliver / up to one megawatt of power / when its turbines / are turning in strong winds.','megawatt 作可数计量单位，1 MW = 1,000,000 watts。','风电场的大规模输出用兆瓦计量，符合 s1。'),M('The engineer recorded one megawatt as one thousand watts, confusing it with a much smaller unit.','The engineer recorded one megawatt as one million watts.','一兆瓦等于一百万瓦，不是一千瓦。','measurement'),[Q('One megawatt equals?','one million watts','one hundred watts','one thousand megawatts','1 MW = 1,000,000 W。','measurement'),Q('What output was measured?','the wind farm’s electrical power','the turbine’s melody','the farm’s membership','兆瓦用于表示风电场输出功率。'),Q('Mega- in megawatt indicates a factor of?','one million','one thousand','one hundred','mega- 表示百万倍。','measurement'),Q('Megawatts are useful for describing?','large power output','a person’s mood','a city’s population only','电站和风场的输出常用兆瓦表示。')]);
P('melancholy','Melancholy came through Latin from Greek melankholia, “black bile”; it means lasting sadness or describes a sad, thoughtful mood.',[C('melancholy.s1','文学心境','A quiet melancholy settled over the narrator after the train carried her away from her childhood town.','火车载她离开童年生活的城镇后，一种安静的忧郁笼罩了叙述者。','A quiet melancholy settled / over the narrator / after the train carried her away / from her childhood town.','melancholy 作名词，指持续而深沉的悲伤。','离开故乡引发较持久的忧伤，符合 s1。'),C('melancholy.s2','音乐氛围','The cello played a melancholy tune that sounded sad and thoughtful rather than dramatic.','大提琴奏出一段忧郁的曲调，听起来悲伤而沉思，并不戏剧化。','The cello played / a melancholy tune / that sounded sad and thoughtful / rather than dramatic.','melancholy 作形容词修饰 tune，描述使人忧伤或沉思的氛围。','曲调本身带忧伤沉思的情绪，符合 s2。')],M('The story’s melancholy mood was cheerful and carefree, with no sadness or reflection at all.','The story’s melancholy mood was quiet and sad, with a reflective tone.','完全欢快无忧不符合忧郁氛围。'),[Q('Melancholy as a feeling is?','deep, lasting sadness','brief excitement','a medical dose','melancholy 指深沉、持久的忧伤。'),Q('A melancholy tune sounds?','sad and thoughtful','loud and comic','like a city map','形容词义描写忧伤沉思的曲调。'),Q('What caused the narrator’s sadness?','leaving her childhood town','finding a megawatt','attending a sports meet','离开童年故乡使她感到忧郁。'),Q('Which sentence uses melancholy as an adjective?','They heard a melancholy cello piece.','A melancholy lasted all year.','She was a melancholy of sadness.','melancholy 可作形容词修饰曲子。','grammar')]);
P('melange','Melange is borrowed from French mélange, “mixture,” and means a varied blend of people, styles, colours, or substances.',C('melange.s1','城市文化','The neighbourhood is a melange of languages and cuisines, reflecting generations of migration to the port.','这个街区融合了多种语言和菜系，反映出几代人迁居港口的历史。','The neighbourhood is / a melange of languages and cuisines / reflecting generations / of migration to the port.','melange 作可数名词，常用 a melange of 表示多样混合。','不同语言和菜系汇聚，符合 s1。'),M('The curator called the exhibition a melange even though every item was identical in colour, style, and origin.','The curator called the exhibition a melange because it combined works from different cultures and styles.','完全相同的展品不构成多样混合。'),[Q('A melange is?','a varied mixture','a single uniform item','a million watts','melange 表示多样混合。'),Q('What formed the neighbourhood’s melange?','different languages and cuisines','one repeated melody','a single medical treatment','街区汇聚了多种语言与菜系。'),Q('Which construction is common?','a melange of styles','melange at styles','a melange by one only','常说 a melange of something。','collocation'),Q('Melange came into English from?','French','Old English','Afrikaans only','melange 源自法语 mélange。')]);
P('melanin','Melanin comes from Greek melas (“black”) and names the natural pigment that contributes to the colour of skin, hair, and eyes.',C('melanin.s1','生物学课程','Melanin protects skin from some ultraviolet radiation and also contributes to differences in skin and hair colour.','黑色素能帮助皮肤抵御部分紫外线，也会影响皮肤和头发颜色的差异。','Melanin protects skin / from some ultraviolet radiation / and also contributes / to differences in skin and hair colour.','melanin 作不可数生物学名词，指天然色素。','色素与皮肤、头发颜色有关，符合 s1。'),M('The textbook said melanin is a hormone that controls when a person falls asleep.','The textbook said melanin is a pigment that contributes to skin, hair, and eye colour.','控制睡眠周期的是褪黑激素 melatonin，不是色素 melanin。','confusable'),[Q('Melanin is a natural?','pigment','sleep hormone','city region','melanin 是天然色素。'),Q('Which features can melanin colour?','skin and hair','rail lines and highways','a cello melody','黑色素影响皮肤和头发颜色。'),Q('Melanin can help protect skin from some?','ultraviolet radiation','marble dust only','meeting agendas','黑色素可帮助抵御部分紫外线。'),Q('Which similarly spelled word is a sleep-related hormone?','melatonin','melanin','melange','melatonin 与睡眠周期相关，melanin 是色素。','confusable')]);
P('melatonin','Melatonin is a coined biological name for a hormone involved in regulating the daily sleep-wake cycle.',C('melatonin.s1','睡眠节律','The doctor explained that melatonin is involved in the body’s daily sleep-wake rhythm and discussed the patient’s routine.','医生解释褪黑激素参与人体每日睡眠—觉醒节律，并与患者讨论了作息。','The doctor explained / that melatonin is involved in the body’s daily sleep-wake rhythm / and discussed / the patient’s routine.','melatonin 作不可数医学名词，指参与昼夜节律的激素。','对话涉及激素与睡眠节律的关系，符合 s1。'),M('The label described melatonin as the pigment that colours hair and skin.','The label described melatonin as a hormone involved in the sleep-wake cycle.','皮肤和头发色素是 melanin，不是 melatonin。','confusable'),[Q('Melatonin is a hormone involved in?','the daily sleep-wake cycle','the colour of skin only','the size of a megacity','melatonin 参与调节睡眠—觉醒节律。'),Q('What did the doctor discuss with the patient?','the patient’s routine','the Mediterranean coastline','a medieval manuscript','医生讨论了患者的作息。'),Q('Which word names the pigment that colours skin and hair?','melanin','melatonin','melodrama','melanin 是色素，melatonin 是激素。','confusable'),Q('Melatonin belongs to which subject area?','medicine and biology','maritime law','music theory','它是参与生理节律的激素。')]);
P('Melbourne','Melbourne is the proper name of the coastal capital city of the Australian state of Victoria.',C('Melbourne.s1','城市地理','Melbourne sits in southeastern Australia, and its tram network carries residents through the city centre.','墨尔本位于澳大利亚东南部，有轨电车网络载着居民穿行于市中心。','Melbourne sits / in southeastern Australia / and its tram network / carries residents through the city centre.','Melbourne 是专有地名，首字母大写，指维多利亚州首府。','东南澳大利亚及电车交通符合城市地理信息。'),M('The atlas placed Melbourne in northern Europe and described it as the capital of Victoria, Canada.','The atlas placed Melbourne in southeastern Australia as the capital of Victoria.','墨尔本位于澳大利亚维多利亚州，不在欧洲或加拿大。'),[Q('Melbourne is a city in?','southeastern Australia','the Mediterranean Sea','medieval France','Melbourne 位于澳大利亚东南部。'),Q('Melbourne is the capital of which state?','Victoria','Medicare','Massachusetts','它是澳大利亚维多利亚州首府。'),Q('What transport network is mentioned?','trams','marshland paths only','maraca rhythms','例句提到墨尔本的有轨电车网络。'),Q('How should the city name begin?','with a capital M','with a lowercase m','with a hyphen','Melbourne 是专有地名，应大写。','capitalization')]);
P('mellow','Mellow may relate to a softened or ripened quality; it describes smooth, gentle flavour or sound, and a calm, easy-going person.',[C('mellow.s1','风味描述','The cheese had a mellow flavour after ageing, with no sharp bitterness to overpower the herbs.','这块奶酪陈放后味道醇和，没有尖锐的苦味盖过香草气息。','The cheese had / a mellow flavour / after ageing / with no sharp bitterness.','mellow 作形容词可描述味道、颜色或声音柔和顺滑。','奶酪风味醇和、不刺激，符合 s1。'),C('mellow.s2','性格变化','After years of teaching, Mr Chen became more mellow and patient with beginners’ mistakes.','教书多年后，陈老师变得更随和，也更能耐心面对初学者的错误。','After years of teaching / Mr Chen became more mellow / and patient / with beginners’ mistakes.','mellow 也可描述性格变得平和、随和。','经验使他耐心温和，符合 s2。')],M('The wine tasted mellow because it was harsh, sour, and painfully sharp on the tongue.','The wine tasted mellow because it was smooth and gentle rather than harsh.','尖锐刺激的口感与 mellow 相反。'),[Q('A mellow flavour is?','smooth and gentle','harsh and sharply bitter','a medical instruction','mellow 可形容醇和柔顺的味道。'),Q('A mellow person is often?','calm and easy-going','domineering and impatient','a sleep hormone','mellow 也可形容性格随和。'),Q('What changed Mr Chen’s manner?','years of teaching experience','a million watts','a Melbourne tram','多年教学经验使他更随和耐心。'),Q('Which sound could be mellow?','a soft, warm cello tone','a piercing alarm','a silent map','声音柔和温暖可称 mellow。')]);
P('melodic','Melodic is formed from melody plus -ic and means having or relating to a tuneful, pleasing line of music.',C('melodic.s1','音乐评论','The singer delivered a melodic chorus that listeners could hum after hearing it once.','歌手唱出一段旋律优美的副歌，听众听过一次就能哼出来。','The singer delivered / a melodic chorus / that listeners could hum / after hearing it once.','melodic 作形容词修饰 chorus，突出旋律性。','副歌易记且有悦耳旋律，符合 s1。'),M('The reviewer called the song melodic even though it had no tune, repeated notes, or musical line.','The reviewer called the song melodic because it had a clear, pleasing tune.','没有旋律线的作品不能称为 melodic。'),[Q('A melodic chorus has?','a tuneful, pleasing musical line','only spoken dialogue','a high population','melodic 表示有悦耳旋律的。'),Q('What could listeners do after hearing it once?','hum the chorus','masticate the chorus','build a megacity','副歌旋律容易记忆，听众能哼出来。'),Q('Melodic is formed from melody plus?','-ic','-dom','-less','melody 加 -ic 构成 melodic。','word-formation'),Q('Which phrase is natural?','a melodic phrase','a melodyic phrase','melodically tune','melodic 可修饰 phrase。','grammar')]);
P('melodious','Melodious combines melody and -ous and describes music or other sounds that are pleasant to hear.',[C('melodious.s1','鸟鸣描写','A melodious blackbird sang from the garden wall while the neighbours opened their windows to listen.','一只鸣声悦耳的乌鸫在花园墙上歌唱，邻居们打开窗户聆听。','A melodious blackbird sang / from the garden wall / while the neighbours / opened their windows to listen.','melodious 作形容词描述像音乐一样悦耳的声音。','鸟鸣令邻居停下来倾听，符合 s1。'),C('melodious.s2','声音评价','The speaker’s voice was melodious and pleasant to listen to, even during a long technical presentation.','演讲者的声音悦耳动听，即使技术报告很长也让人愿意听下去。','The speaker’s voice was / melodious and pleasant to listen to / even during / a long technical presentation.','melodious 也可广义指听起来悦耳的声音。','人声悦耳，即使内容较长也不刺耳。')],M('The blackbird’s melodious song was painfully harsh and made every listener cover their ears.','The blackbird’s melodious song was smooth and pleasant enough to draw neighbours to their windows.','刺耳难听的声音不符合 melodious。'),[Q('A melodious blackbird has?','a pleasant musical-sounding call','a medicine label','a marble nest','melodious 描述悦耳如音乐的声音。'),Q('The speaker’s voice was melodious means it was?','pleasant to listen to','too harsh to hear','a medium-sized city','melodious 可泛指悦耳动听。'),Q('Who opened their windows to listen?','the neighbours','a council meeting','the meerkat group','邻居们打开窗户听鸟鸣。'),Q('Which word is closest to melodious?','tuneful','mediocre','meek','tuneful 同样表示旋律悦耳。')]);
P('melodrama','Melodrama combines Greek melos (“song”) and drama; it is a sensational, highly emotional story or an exaggerated emotional reaction.',C('melodrama.s1','戏剧情节','The play is a melodrama filled with sudden rescues, hidden identities, and emotional speeches.','这出戏是一部充满意外营救、隐藏身份和煽情演说的情节剧。','The play is / a melodrama / filled with sudden rescues, hidden identities, / and emotional speeches.','melodrama 作可数名词，指情节夸张、情感强烈的戏剧或故事。','营救、身份秘密和煽情演说体现情节剧特色。'),M('The reviewer called the quiet documentary a melodrama although it contained no sensational events or heightened emotions.','The reviewer called the play a melodrama because it relied on sensational events and intense emotions.','平静客观且没有夸张情节的纪录片不符合此义。'),[Q('A melodrama often features?','sensational events and strong emotions','a neutral list of measurements','a scientific sleep hormone','melodrama 指情节夸张、情感强烈的戏剧故事。'),Q('What appeared in the play?','rescues and hidden identities','a megawatt turbine','a Melbourne tram schedule','剧中有意外营救和隐藏身份。'),Q('A person’s melodrama may mean?','an exaggerated emotional reaction','a pleasant tune','a medical science degree','该词也可形容现实中过度戏剧化的反应。'),Q('Which phrase is natural?','a melodrama about mistaken identity','a melodrama of one watt','a melodramatic of a play','melodrama 可描述煽情情节剧。')]);
P('melody','Melody comes from Greek melōidia, “singing”; it means a sequence of notes forming a tune or, more broadly, a pleasant pattern of sound.',[C('melody.s1','乐曲创作','The flutist repeated the melody slowly so the orchestra could learn the main tune before rehearsing the harmony.','长笛手慢慢重复旋律，让乐团在排练和声前先熟悉主调。','The flutist repeated / the melody slowly / so the orchestra could learn / the main tune before rehearsing the harmony.','melody 作名词，指构成曲调的一系列音符。','乐团学习主旋律，符合 s1。'),C('melody.s2','环境声音','The gentle melody of rain on the roof helped the children settle down after their journey.','雨滴落在屋顶上的柔和声响让孩子们旅途后平静下来。','The gentle melody of rain / on the roof / helped the children / settle down after their journey.','melody 也可泛指悦耳、有规律的声音组合。','雨声形成令人平静的悦耳声响。')],M('The melody was a sequence of random noises with no tune or repeated musical pattern.','The melody was a sequence of notes forming a recognisable tune.','无曲调和音符组织的随机噪音不是旋律。'),[Q('A melody is a sequence of notes that forms?','a tune','a medical plan','a city region','melody 指一段曲调。'),Q('The melody of rain means?','its pleasant pattern of sound','the rain’s chemical pigment','a tune made only by a flute','melody 可泛指悦耳的声音模式。'),Q('Who repeated the main tune for the orchestra?','the flutist','the Melbourne mayor','the meerkat','长笛手帮助乐团熟悉主旋律。'),Q('Which phrase is natural?','learn the melody','melt the melody into a city','a melodic melodyly','learn the melody 是自然表达。','collocation')]);
P('melon','Melon came through French from Latin melopepon, ultimately from Greek for a gourd-like fruit; it names a large sweet fruit such as watermelon or honeydew.',C('melon.s1','水果摊位','The market seller cut a ripe melon into wedges and offered samples of its sweet orange flesh.','市场摊贩把熟甜瓜切成楔形，并请顾客品尝香甜的橙色果肉。','The market seller cut / a ripe melon into wedges / and offered samples / of its sweet orange flesh.','melon 作可数名词，指甜瓜类大型甜果。','果肉甜且可切块食用，符合 s1。'),M('The vendor labelled the savoury green leaf a melon, although it was not a fruit and contained no flesh or seeds.','The vendor labelled the large sweet fruit a melon and cut it into wedges.','叶片不是甜瓜类水果。'),[Q('A melon is a?','large sweet fruit','sleep hormone','type of city','melon 指大型甜果。'),Q('What colour was the melon flesh in the example?','orange','blue','maroon','例句说果肉为橙色。'),Q('Where was the melon sold?','at a market','in a marrow','at a medical science lecture','市场摊贩出售甜瓜。'),Q('Which food is a kind of melon?','watermelon','marshmallow only','margarine','watermelon 属于瓜类水果。')]);
P('melt','Melt comes from Old English meltan; it means to change from solid to liquid through heat or to become softer emotionally.',[C('melt.s1','冰雪变化','The last patch of snow began to melt when warm rain fell on the hillside.','暖雨落在山坡上后，最后一片积雪开始融化。','The last patch of snow / began to melt / when warm rain / fell on the hillside.','melt 作不及物动词，描述固体受热变成液体。','温暖天气使雪融化，符合 s1。'),C('melt.s2','情感变化','Her stern expression melted when the child handed her a drawing made especially for her.','孩子递给她一幅专门为她画的画后，她严肃的表情柔和了下来。','Her stern expression melted / when the child handed her / a drawing / made especially for her.','melt 可比喻态度或情感变得柔和。','礼物让她的严肃神情软化，符合 s2。')],M('The snow melted by becoming colder and harder throughout the warm afternoon.','The snow melted as rising temperatures changed it from solid ice into water.','温度升高使雪融化，变冷变硬则相反。'),[Q('Snow melts when it?','changes from solid ice to liquid water','turns into a louder sound','becomes a medium-sized city','melt 的物理义是固体受热转为液体。'),Q('Her expression melted means she?','became less stern or more tender','turned physically into water','joined a meeting','melt 可比喻表情或情绪变柔和。'),Q('What began to melt on the hillside?','the last patch of snow','a medieval manuscript','a meerkat burrow','暖雨使积雪开始融化。'),Q('Which sentence uses melt figuratively?','The child’s apology melted his anger.','The ice melted in the sun.','The wax melted near the flame.','apology 令怒气消散，属于比喻义。')]);
P('meltdown','Meltdown combines melt and down; it can mean a reactor core melting or a disastrous collapse of a system, market, or self-control.',C('meltdown.s1','工业安全','The reactor’s emergency cooling system prevented a meltdown after the power supply failed.','电力供应故障后，反应堆的紧急冷却系统防止了堆芯熔毁。','The reactor’s emergency cooling system / prevented a meltdown / after the power supply failed.','meltdown 作可数名词，核能语境指反应堆堆芯熔毁。','冷却系统阻止严重的核事故，符合 s1。'),M('The cooling system caused a reactor meltdown by keeping the core safely below its critical temperature.','The cooling system prevented a reactor meltdown by keeping the core from overheating.','将堆芯维持在安全温度以下是防止熔毁。'),[Q('A reactor meltdown involves?','the reactor core melting dangerously','a melody played at a meeting','a small amount of medicine','meltdown 的核能义指堆芯熔毁。'),Q('What prevented the accident?','the emergency cooling system','a medieval rule','a melon seller','紧急冷却系统防止了熔毁。'),Q('A market meltdown is?','a disastrous collapse of the market','a gentle rise in value','a musical performance','meltdown 也可指市场或系统崩溃。'),Q('Which phrase is natural?','a public meltdown after losing control','a meltdown of a meadow’s flowers only','meltdownly calm','meltdown 可比喻失控或系统崩溃。')]);
P('melting','Melting is formed from melt plus -ing and describes a substance becoming liquid or a tender, softened expression.',[C('melting.s1','实验观察','The melting wax collected in a shallow tray beneath the candle as the room warmed.','房间变暖后，融化的蜡收集在蜡烛下方的浅盘里。','The melting wax collected / in a shallow tray / beneath the candle / as the room warmed.','melting 作形容词或分词，表示正在由固态转为液态。','蜡受热融化并流入盘中，符合 s1。'),C('melting.s2','表情描写','He gave the puppy a melting look of tenderness that softened even his usually stern face.','他用充满柔情的眼神看着小狗，连平时严肃的表情也柔和了下来。','He gave the puppy / a melting look of tenderness / that softened / even his usually stern face.','melting 可形容温柔动人的情感表达。','柔情让严肃神情变软，符合 s2。')],M('The melting wax stayed completely solid and hard even beside the burning candle.','The melting wax softened and flowed into the tray beside the candle.','完全坚硬不变的蜡没有在融化。'),[Q('Melting wax is wax that is?','becoming liquid through heat','turning into a city','getting louder','melting 描写固体受热融化。'),Q('A melting look is?','tender and emotionally soft','a technical measurement','a cold, hostile expression','melting 也可形容温柔动人的目光。'),Q('Where did the wax collect?','in a shallow tray','in a Mediterranean harbour','inside a meerkat burrow','融蜡流入蜡烛下方的浅盘。'),Q('Which use is figurative?','a melting look of tenderness','melting ice in spring','melting wax beside a flame','温柔神情中的 melting 是比喻义。')]);
P('meltwater','Meltwater combines melt and water and means runoff produced when snow, ice, or a glacier melts.',C('meltwater.s1','山地水文','Meltwater from the glacier filled the stream each spring and carried fine sediment into the valley.','每年春天，冰川融水注满溪流，并把细小沉积物带入山谷。','Meltwater from the glacier / filled the stream / each spring / and carried fine sediment into the valley.','meltwater 作不可数名词，指冰雪融化后形成的径流。','冰川春季融水进入溪流，符合 s1。'),M('The stream was called meltwater even though it came only from a dry underground pipe and no snow or ice melted.','The stream was called meltwater because it flowed from melting glacier ice.','没有冰雪融化就不能称为融水。'),[Q('Meltwater comes from?','melting snow, ice, or glaciers','a medical science lab','a city marketplace','meltwater 是冰雪或冰川融化后的水。'),Q('When did the glacier fill the stream?','each spring','only at lunchtime','during every meeting','冰川春季融水注入溪流。'),Q('What did the water carry?','fine sediment into the valley','marshmallows to Melbourne','melatonin into the sea','融水把细小沉积物带入山谷。'),Q('Which phrase is natural?','glacial meltwater','melting water from a medication','meltwater of a melody','glacial meltwater 是自然搭配。','collocation')]);
P('member','Member comes through Old French from Latin membrum (“limb”); it means someone belonging to a group or a person elected to a parliament.',[C('member.s1','俱乐部登记','Each member received a card that allowed access to the community gym during staffed hours.','每位会员都收到一张卡，可在工作人员值班时进入社区健身房。','Each member received a card / that allowed access / to the community gym / during staffed hours.','member 作可数名词，指属于俱乐部、家庭或组织的人。','会员卡授予俱乐部成员使用权，符合 s1。'),C('member.s2','议会报道','The member of parliament asked the minister to explain the delays in the regional health service.','这名议员要求部长解释地区医疗服务的延误问题。','The member of parliament asked the minister / to explain / the delays / in the regional health service.','member of parliament 指经选举进入议会的议员。','向部长质询的议会成员符合 s2。')],M('The gym member was a stranger with no club registration, but the staff treated him as a registered member.','The gym member held a valid club card and belonged to the organisation.','没有登记或会员资格的人不能称为该健身房会员。'),[Q('A gym member is?','someone who belongs to the club','the person who designed the gym','a medication','member 指属于某组织的人。'),Q('A member of parliament is?','an elected representative','a gym customer only','a melody','member 也可指议员。'),Q('What did each gym member receive?','an access card','a megawatt','a melon','会员得到健身房出入卡。'),Q('Which phrase is natural?','a member of the committee','a member with the parliament of','a membering committee','常说 a member of a group。','collocation')]);
P('membership','Membership comes from member plus -ship and means the state of belonging to a group or the group’s members collectively.',[C('membership.s1','入会资格','Membership in the research society requires an application and approval from two current members.','加入研究学会需要提交申请，并获得两名现任成员的批准。','Membership in the research society requires / an application / and approval / from two current members.','membership 作不可数名词，membership in/of 表示会员资格。','申请与批准是获得资格的条件。'),C('membership.s2','全体成员','The club’s membership voted to extend the opening hours after reviewing the latest survey.','俱乐部全体会员查看最新调查后，投票决定延长开放时间。','The club’s membership voted / to extend the opening hours / after reviewing / the latest survey.','membership 也可集合指一个组织的全体成员。','会员集体投票，符合 s2。')],M('Her membership was approved although she had not applied, paid any fee, or received permission to join.','Her membership was approved after she applied and received the required sponsors’ support.','没有申请或批准就不能说获得会员资格。'),[Q('Membership in a society is?','the state of belonging to it','a medication dose','a melody','membership 指会员资格。'),Q('The club’s membership voted means?','the club’s members acted collectively','only one visitor voted','the club itself became a member of parliament','membership 可集合指全体成员。'),Q('What was needed to join the society?','an application and two members’ approval','a Melbourne tram ticket','a melon','加入需要申请和现任成员批准。'),Q('Which phrase is natural?','membership in the society','membership with society of','a membershiping society','membership 常与 in 或 of 连用。','collocation')]);
P("membrane","Membrane entered English through Latin membrana, meaning a skin or parchment, from membrum, a bodily limb.",C("membrane.s1","生物结构","The cell membrane controls which substances can enter or leave the cell, helping it maintain a stable internal environment.","细胞膜控制哪些物质可以进出细胞，帮助细胞维持稳定的内部环境。","The cell membrane controls / which substances can enter or leave / the cell / helping it maintain a stable internal environment.","membrane 指包围、衬覆或分隔结构的薄层。","例句中的膜形成细胞边界并调节物质进出。"),M("The biologist called the thick solid bone around the cell a membrane, even though it formed no thin boundary layer.","The biologist called the thin boundary layer around the cell a membrane because it separates the cell from its surroundings.","膜是薄层边界；实心骨头不符合这个定义。"),[Q("A cell membrane mainly forms a?","thin boundary around the cell","solid bone inside the cell","written message to a colleague","membrane 是包围或分隔结构的薄层。"),Q("What does the membrane regulate in the example?","movement of substances into and out of the cell","the cell’s musical rhythm","the cell’s monthly cycle","细胞膜控制物质进出。"),Q("Which object is also naturally called a membrane?","a thin layer lining an organ","a heavy metal thermometer","a group of internet jokes","器官内衬的薄膜符合该词义。"),Q("Which phrase is standard in biology?","cell membrane","cell memento","cell menu","cell membrane 是生物学常用搭配。","collocation")]);
P("meme","Meme was coined by Richard Dawkins in 1976 from Greek sources related to imitation, echoing the sound of gene; the internet-image sense arose later.",[C("meme.s1","文化传播","The researcher described the hand-clapping game as a meme because children copied it and passed it to new groups.","研究者把这个拍手游戏称为文化复制子，因为孩子们会模仿它并把它传给新的群体。","The researcher described / the hand-clapping game as a meme / because children copied it / and passed it to new groups.","meme 可指在群体间模仿、传播的文化单位。","孩子们复制并传播游戏，体现文化传播意义。"),C("meme.s2","网络内容","A photograph of the sleepy cat became an internet meme after users added different captions and shared their versions.","这只困倦猫咪的照片被用户配上不同文字并分享改编版本后，成了网络迷因。","A photograph of the sleepy cat became / an internet meme / after users added different captions / and shared their versions.","网络 meme 常是被广泛改编和传播的图片、视频或文字。","用户添加文字并分享改编图像，符合网络义。")],M("The cat photograph was called an internet meme, but nobody copied, altered, or shared it with anyone.","The cat photograph became an internet meme when users copied it, added captions, and shared their versions.","无人复制或传播的图片没有体现网络迷因的传播特点。"),[Q("In cultural studies, a meme is something that?","is copied and passed between people","can only be stored in a computer","is a written office instruction","文化 meme 通过模仿在人群中传播。"),Q("Why did the cat photograph become an internet meme?","users added captions and shared versions","it was kept private in one camera","it was printed as a medical label","改编和传播使图片成为网络迷因。","context"),Q("Dawkins coined meme partly to echo which word?","gene","menu","mercy","该词的造词还呼应了 gene 的声音。","word-formation"),Q("Which example best fits the internet sense?","a widely reposted image with changing captions","a one-to-one confidential letter","a thin layer separating two tissues","被广泛转发和改编的图片符合网络义。")]);
P("memento","Memento is Latin for “remember,” the second-person singular imperative of meminisse; English later used it for a reminder or keepsake.",C("memento.s1","旅行纪念","Nora kept a small shell as a memento of the beach where her family had watched the sunrise together.","诺拉留着一枚小贝壳，作为她和家人一起看日出的那片海滩的纪念物。","Nora kept a small shell / as a memento / of the beach / where her family had watched the sunrise together.","memento 指让人想起某个地方或经历的物件。","贝壳被保存下来，帮助诺拉回想那次海滩旅行。"),M("He kept the shell as a memento of the trip, although it had no connection to the journey and reminded him of nothing.","He kept the shell as a memento of the trip because it reminded him of the beach and his family’s visit.","纪念物的用途在于唤起对某事的记忆。"),[Q("A memento is an object kept to?","remind someone of a place or event","measure a planet’s orbit","list available restaurant dishes","memento 是帮助人回忆的纪念物。"),Q("What did Nora keep?","a small shell","a medical prescription","a computer menu","诺拉保存的是一枚小贝壳。"),Q("The shell reminded Nora of?","a family visit to the beach","a company merger","a monthly report","贝壳让她想起与家人的海滩旅行。"),Q("Which item could be a memento?","a ticket saved from a memorable concert","a blank sheet with no personal meaning","a thermometer used to test mercury","演唱会门票可作为那次经历的纪念物。")]);
P("memo","Memo is a shortened form of memorandum, from Latin memorandum, “something to be remembered”; it commonly names a brief workplace message.",C("memo.s1","办公室沟通","The director sent a memo reminding staff to submit their travel expenses before the end of the month.","主任发了一份备忘录，提醒员工在月底前提交差旅费用。","The director sent a memo / reminding staff / to submit their travel expenses / before the end of the month.","memo 是办公室或公司内部使用的简短书面通知。","主任以简短书面消息告知员工截止日期。"),M("The director called the long public biography of the company founder a memo, although it was not a brief workplace message.","The director called the short internal notice about expense deadlines a memo.","长篇传记不属于简短的办公室信息。"),[Q("A workplace memo is usually?","a brief written message","a full-length personal biography","a mythical sea creature","memo 指简短的办公室书面消息。"),Q("What did the director remind staff to submit?","travel expenses","their lunch menus","a list of wild animals","备忘录提醒员工提交差旅费用。"),Q("Who received the memo?","the staff","customers at a restaurant","members of parliament only","主任把通知发给员工。"),Q("Which heading would suit a memo?","Expense reports due by 30 June","A life story in twelve chapters","How to identify a meridian","简短工作通知适合作为 memo 标题。")]);
P("memoir","Memoir came through French mémoire from Latin memoria, “memory”; it is a personal account written from the author’s memories.",C("memoir.s1","个人回忆","In her memoir, the retired nurse recounts the people and difficult decisions that shaped her work during the flood.","这位退休护士在回忆录中讲述了洪灾期间影响她工作的那些人和艰难决定。","In her memoir / the retired nurse recounts / the people and difficult decisions / that shaped her work during the flood.","memoir 通常以作者亲历的事件和回忆为基础。","护士从个人经历出发讲述洪灾时期的工作。"),M("The nurse called her memoir a complete biography of a stranger whose life she had never known or researched.","The nurse called her memoir a personal account of events and people she had experienced herself.","memoir 以作者自己的回忆为基础，而非替陌生人写完整传记。"),[Q("A memoir is primarily based on?","the writer’s personal memories and experiences","a stranger’s complete life story written by someone else","a restaurant’s list of available dishes","memoir 是作者根据自身经历写成的叙述。"),Q("What does the retired nurse recount?","people and decisions from her work during the flood","the history of a distant planet","instructions for repairing a membrane","她回忆洪灾期间的工作经历。"),Q("Which narrator is most likely writing a memoir?","a witness describing events she lived through","an editor listing a company’s products","a scientist defining the meridian line","亲历者回述自己的经历，符合 memoir。"),Q("Which phrase best describes the book?","a memoir of life in a rural clinic","a memoir listing today’s lunch prices","a memoir that contains no personal recollections","农村诊所经历的个人回忆录是自然说法。","collocation")]);
P("memorable","Memorable combines memory with the adjective-forming suffix -able and means worth remembering because it is special or striking.",C("memorable.s1","难忘经历","The final performance was memorable because the whole cast sang together beneath a sky full of fireworks.","压轴演出令人难忘，因为全体演员在烟花绽放的夜空下合唱。","The final performance was memorable / because the whole cast sang together / beneath a sky / full of fireworks.","memorable 表示值得记住、令人难忘的。","烟花下的全体合唱使演出格外难忘。"),M("The evening was memorable because everyone forgot it immediately and could recall nothing about it the next day.","The evening was memorable because its shared songs and fireworks stayed in everyone’s minds.","很快被忘掉的经历不符合 memorable 的意思。"),[Q("A memorable event is?","worth remembering","impossible to describe","only a written reminder","memorable 表示值得记住的。"),Q("Why was the performance memorable?","the cast sang together under fireworks","the audience left before it began","the concert had no performers","合唱与烟花令演出难忘。"),Q("Which adjective is closest in meaning?","unforgettable","menial","mercantile","unforgettable 与 memorable 意义相近。"),Q("Which sentence uses memorable naturally?","It was a memorable first visit to the city.","She memorabled the date before breakfast.","The soup was memorable with no taste and no aroma.","memorable 是形容词，可修饰 visit。","grammar")]);
P("memorandum","Memorandum is the Latin gerundive of memorare, “to remind”; it names a short written note, including a document recording an agreement.",[C("memorandum.s1","工作便笺","The manager circulated a memorandum outlining the new procedure for booking shared meeting rooms.","经理传阅了一份备忘录，说明预订共享会议室的新流程。","The manager circulated / a memorandum / outlining the new procedure / for booking shared meeting rooms.","memorandum 可指正式或简短的书面通知。","文件概述了内部预订流程。"),C("memorandum.s2","协议记录","The two organisations signed a memorandum of understanding that recorded their plans for a joint research project.","两个组织签署了谅解备忘录，记录了共同开展研究项目的计划。","The two organisations signed / a memorandum of understanding / that recorded their plans / for a joint research project.","memorandum of understanding 用文件记录双方协议或合作意向。","签署文件记载了双方共同研究的计划。")],M("The organisations signed a memorandum of understanding, but the document recorded no terms, intentions, or agreement between them.","The organisations signed a memorandum of understanding to record their shared intentions and proposed project.","谅解备忘录应记录双方的意向或协议内容。"),[Q("A workplace memorandum often sets out?","information or instructions in writing","a full personal life story","a list of restaurant meals","memorandum 可指书面通知或便笺。"),Q("A memorandum of understanding records?","the parties’ shared intentions or agreed plans","the weather forecast alone","the complete history of one signatory","谅解备忘录记录共同意向或约定计划。"),Q("What procedure did the manager outline?","booking shared meeting rooms","choosing a meridian","treating a membrane","经理说明了会议室预订流程。"),Q("Which document name fits a signed cooperation plan?","memorandum of understanding","memento of understanding","menu of understanding","memorandum of understanding 是常见文件名称。","collocation")]);
P("memorial","Memorial comes from Latin memorialis, “mindful or commemorative,” based on memoria, “memory”; it can name a tribute or describe something commemorative.",[C("memorial.s1","公共纪念","Residents gathered at the war memorial to lay flowers and read the names engraved on its stone panels.","居民聚集在战争纪念碑前献花，并阅读刻在石板上的姓名。","Residents gathered / at the war memorial / to lay flowers / and read the names engraved on its stone panels.","memorial 作名词可指纪念逝者的建筑、物件或仪式。","居民在纪念碑前献花并追思逝者。"),C("memorial.s2","追悼活动","The school held a memorial concert for its former music teacher, choosing pieces that she had taught to generations of pupils.","学校为已故的前音乐教师举办了追悼音乐会，演奏她曾教过几代学生的曲目。","The school held / a memorial concert / for its former music teacher / choosing pieces that she had taught to generations of pupils.","memorial 作形容词表示为纪念某人而举行或制作的。","音乐会专为纪念已故教师而举办。")],M("The town called the empty commercial billboard a memorial although it honoured no person and commemorated no event.","The town called the monument a memorial because it was built to honour those who had died in the war.","没有纪念对象或用途的广告牌不属于纪念物。"),[Q("A war memorial is designed to?","honour and remember people connected with the war","advertise a new restaurant","record the day’s menu","war memorial 用来纪念相关逝者或事件。"),Q("A memorial concert is held?","to remember and honour someone","to explain how to repair a machine","to announce a company merger","memorial 作形容词表示纪念性质。"),Q("What did residents read at the memorial?","names engraved on stone panels","a list of computer settings","the restaurant’s prices","居民阅读石板上刻的姓名。"),Q("Which phrase uses memorial as an adjective?","a memorial service for the composer","a membrane service for the composer","a meridian service for the composer","memorial service 指纪念或追悼仪式。","collocation")]);
P("memorize","Memorize was formed with -ize from memory and means to learn something so that it can be recalled exactly.",C("memorize.s1","学习方法","Before the recital, Lina used short daily sessions to memorize the poem rather than trying to learn all forty lines at once.","演出前，莉娜每天分几次练习来背诵这首诗，而不是试图一次记下全部四十行。","Before the recital / Lina used short daily sessions / to memorize the poem / rather than trying to learn all forty lines at once.","memorize 是通过学习使内容能被准确回想。","莉娜分段练习以便背熟诗句。"),M("Lina said she had memorized the poem, but she had never read it and could not recall a single line.","Lina memorized the poem by practising its lines in short sessions until she could recite them.","没有学习且无法回想内容，不构成 memorizing。"),[Q("To memorize a poem is to?","learn it so you can recall it","repair its torn pages","write a short office message","memorize 表示背熟、记住。"),Q("How did Lina prepare?","she practised in short daily sessions","she copied the title without reading the poem","she asked the audience to write it","她每天分段练习诗歌。"),Q("What could Lina do after memorizing the poem?","recite its lines from memory","change the poem into a menu","measure the poem’s longitude","记熟后可以凭记忆背诵。"),Q("Which phrase is natural?","memorize a set of instructions","memorize somebody with a set of instructions","memorize into the classroom","memorize 可直接接要记住的内容。","grammar")]);
P("memory","Memory comes through Old French memorie from Latin memoria, related to memor, “mindful”; it can mean recall, a recollection, or computer storage.",[C("memory.s1","记忆能力","Regular sleep can support memory, making it easier for students to retain facts they studied during the day.","规律睡眠有助于记忆，使学生更容易保留白天学过的事实。","Regular sleep can support memory / making it easier for students / to retain facts / they studied during the day.","memory 可指记住信息的能力。","此处说睡眠支持学生保留所学信息的能力。"),C("memory.s2","往事回忆","The smell of warm bread brought back a childhood memory of visiting her grandmother’s kitchen.","热面包的气味唤起了她儿时去祖母厨房的回忆。","The smell of warm bread / brought back a childhood memory / of visiting / her grandmother’s kitchen.","memory 也可指过去某件被记住的事。","气味唤回了她对童年经历的具体回忆。"),C("memory.s3","计算机存储","The editing software needs more memory to keep the large video file open while the colour settings are adjusted.","调整色彩设置时，编辑软件需要更多内存才能保持大型视频文件处于打开状态。","The editing software needs more memory / to keep the large video file open / while the colour settings / are adjusted.","计算机语境中的 memory 指存储信息的部件或容量。","软件需要额外存储空间来处理视频文件。")],M("The computer technician said memory stores no information and is used only to display a screen’s colour.","The computer technician added memory so the system could store and work with more information.","计算机 memory 用于存储信息，并非只负责显示颜色。"),[Q("A student with a good memory can?","remember information well","repair a broken screen","write a formal agreement","memory 的 s1 指记忆能力。"),Q("A childhood memory is?","something remembered from the past","a new computer component","a written workplace notice","memory.s2 指过去的回忆。","distinction"),Q("Why did the editing software need more memory?","to keep a large video file open while editing","to improve the smell of the bread","to print a memorial plaque","软件需要更多内存处理大型视频。","context"),Q("Which use is about recollection rather than computing?","That song brings back a happy memory.","The laptop has 16 gigabytes of memory.","The program uses memory while rendering.","歌曲唤起往事，使用的是回忆义。","distinction")]);
P("menace","Menace came through Old French from Latin minaciae, “threats”; it can name a danger or threatening person, and is also a verb meaning to threaten.",[C("menace.s1","公共安全","Loose electrical cables hanging over the flooded path posed a serious menace to anyone trying to reach the shelter.","淹水小路上方垂落的电线对任何试图前往避难所的人都构成严重威胁。","Loose electrical cables / hanging over the flooded path / posed a serious menace / to anyone trying to reach the shelter.","menace 作名词可指可能造成伤害的危险或威胁。","垂落的电线可能伤人，因此构成危险。"),C("menace.s2","人物评价","The neighbour called the repeat vandal a menace after he damaged several parked bicycles in the same week.","邻居称这名屡次破坏公物的人是个麻烦人物，因为他一周内损坏了好几辆停放的自行车。","The neighbour called / the repeat vandal a menace / after he damaged / several parked bicycles in the same week.","menace 可指危险或令人厌烦的人。","这个人反复破坏他人物品，符合人物义。"),C("menace.s3","口头威胁","The gang sent messages to menace the shop owner into paying money for protection.","团伙发消息恐吓店主，逼他付钱以换取保护。","The gang sent messages / to menace the shop owner / into paying money / for protection.","作动词时 menace someone 表示威胁或恐吓某人。","消息用于恐吓店主付款，符合动词义。")],M("The hanging live cable was no menace to walkers because it could not cause harm and was safely disconnected.","The hanging live cable was a menace to walkers because it could cause a dangerous electric shock.","带电且垂落的电线可能伤人，所以是危险源。"),[Q("A loose live cable over a path is a?","potential danger","written reminder","computer storage unit","menace.s1 表示可能造成伤害的危险。"),Q("Calling a repeat vandal a menace describes?","a dangerous or troublesome person","a helpful mentor","a quiet restaurant menu","menace.s2 可指危险或讨厌的人。"),Q("To menace a shop owner is to?","threaten or intimidate the owner","repair the owner’s shop","invite the owner to dinner","menace.s3 是动词，表示威胁恐吓。"),Q("Which use is verbal?","They tried to menace the witness into silence.","The storm was a menace to boats.","That noisy dog is a neighbourhood menace.","menace 接宾语作动词时表示恐吓。","grammar")]);
P("menacing","Menacing is the present participle and adjective from menace, describing something that suggests danger or a likely threat.",C("menacing.s1","气氛描写","The guard gave the trespasser a menacing stare, then pointed toward the exit without saying a word.","守卫用凶狠的目光盯着闯入者，随后一言不发地指向出口。","The guard gave the trespasser / a menacing stare / then pointed toward the exit / without saying a word.","menacing 作形容词表示显出威胁或危险的。","守卫的目光带有威吓意味。"),M("The guard’s menacing smile reassured everyone because it was gentle, welcoming, and gave no hint of danger.","The guard’s menacing stare unsettled the trespasser because it suggested that trouble might follow.","温和友善且毫无威胁的表情与 menacing 相反。"),[Q("A menacing stare suggests?","that something threatening may happen","that the person is offering a keepsake","that a meal is ready","menacing 描写带有威胁意味的表情。"),Q("How did the guard communicate?","with a threatening look and a gesture","by sending a friendly invitation","by displaying a restaurant menu","守卫用凶狠目光和手势示意。"),Q("Which adjective is closest to menacing?","threatening","memorable","merciful","threatening 表达相近的威胁意味。"),Q("Which phrase is natural?","a menacing warning","a menacing of warning","a warning menacingly person","menacing 可直接修饰名词 warning。","grammar")]);
P("menagerie","Menagerie came from French ménagerie, originally referring to a household or place for keeping animals; it now commonly means a collection of wild animals kept for display.",C("menagerie.s1","动物园展览","The travelling menagerie displayed rescued parrots and tortoises, with signs explaining how each animal had been cared for.","巡回珍奇动物展展示了获救的鹦鹉和陆龟，并用标牌说明每只动物曾如何得到照料。","The travelling menagerie displayed / rescued parrots and tortoises / with signs explaining / how each animal had been cared for.","menagerie 指供展示或饲养的一群珍奇动物。","展览中有多种动物并向公众展示。"),M("The keeper called the empty glass cupboard a menagerie, although it held no animals at all.","The keeper called the display of rescued parrots and tortoises a menagerie.","没有动物的柜子不构成动物群或动物展。"),[Q("A menagerie is a collection of?","animals kept or displayed","office memoranda","longitude lines","menagerie 指供饲养或展示的动物群。"),Q("Which animals appeared in the travelling menagerie?","parrots and tortoises","mermaids and meridians","memories and memos","展览展示鹦鹉和陆龟。"),Q("Why were signs included?","to explain the animals’ care","to list the cast’s song lyrics","to record a company merger","标牌说明动物的照料情况。"),Q("Which place could be described as a menagerie?","a collection of rescued wild animals open to visitors","a locked room containing only empty cages","an office with a stack of paperwork","对外展示的野生动物群符合该词义。")]);
P("mend","Mend came through Old French amender and is related to Latin emendare, “to correct”; as a verb it can mean repair something or become healthier.",[C("mend.s1","修补衣物","Ravi used matching thread to mend the torn pocket before wearing the jacket to the interview.","拉维用颜色相配的线补好了撕裂的口袋，然后穿这件夹克去面试。","Ravi used matching thread / to mend the torn pocket / before wearing the jacket / to the interview.","mend 作及物动词，表示修补破损物。","他用线缝补夹克口袋。"),C("mend.s2","康复进展","After several quiet days at home, her health began to mend and she could walk around the garden again.","在家静养几天后，她的健康状况开始好转，又能在花园里散步了。","After several quiet days at home / her health began to mend / and she could walk / around the garden again.","mend 也可不及物地表示健康或状况好转。","病后身体恢复，她能重新散步。")],M("The tailor mended the pocket by cutting it away completely and leaving the jacket with a larger hole.","The tailor mended the pocket by sewing the torn edges together with matching thread.","扩大破洞没有修补衣物，缝合破口才是 mend。"),[Q("To mend a torn pocket is to?","repair it","memorize it","make it more threatening","mend.s1 表示修理或缝补。"),Q("Her health began to mend means she?","started to recover","became worse each day","learned a poem by heart","mend.s2 表示健康好转。"),Q("What did Ravi use to mend the jacket?","matching thread","a mercury thermometer","a restaurant menu","拉维用颜色相配的线修补口袋。"),Q("Which sentence uses mend without a direct object?","After a long illness, his strength slowly mended.","She mended the torn sleeve.","They mended the broken chair.","健康或身体状况可作不及物动词 mend 的主语。","grammar")]);
P("mending","Mending is formed from mend plus -ing and names the act of repairing, or clothes that need to be repaired.",[C("mending.s1","日常修补","On Sunday afternoon, Grandma sat by the window with her mending and repaired two loose buttons.","周日下午，奶奶坐在窗边做针线活，缝好了两颗松脱的纽扣。","On Sunday afternoon / Grandma sat by the window / with her mending / and repaired two loose buttons.","mending 作名词可指修补工作或待补衣物。","缝纽扣属于日常衣物修补。")],M("She put the mending away after finishing every repair, although the basket still held several torn garments needing attention.","She left the mending in the basket because several torn garments still needed repair.","mending 可指尚待修补的衣物，例句说全都修好则与此矛盾。"),[Q("In the example, Grandma’s mending refers to?","clothes being repaired","a group of wild animals","a formal agreement","mending 可指针线修补活。"),Q("What did Grandma repair?","two loose buttons","a cell membrane","a restaurant menu","奶奶缝好了两颗纽扣。"),Q("Which basket could contain mending?","one holding torn clothes waiting to be sewn","one holding only fresh fruit","one holding computer memory chips","待补衣物可统称 mending。"),Q("Which phrase is natural?","sit down with one’s mending","sit down with one’s mendingses","sit down mending the clothes a noun","mending 可作不可数名词表示针线活。","countability")]);
P("menial","Menial came through Anglo-French meinial, referring to household servants; its modern adjective sense describes low-status, often routine work.",[C("menial.s1","工作性质","Although the task was menial, the laboratory assistant completed the repetitive washing carefully because clean glassware was essential to the experiment.","尽管这项工作很琐碎，实验室助理仍认真完成重复的清洗，因为洁净的玻璃器皿对实验至关重要。","Although the task was menial / the laboratory assistant completed / the repetitive washing carefully / because clean glassware was essential to the experiment.","menial 作形容词形容地位低、单调或不需高技能的工作。","重复清洗属于低技能但必要的工作。"),C("menial.s2","家务杂役","The large household employed two menials to carry coal, scrub floors, and perform other humble domestic tasks.","这个大家庭雇了两名杂役搬煤、擦地并做其他卑微的家务。","The large household employed / two menials / to carry coal, scrub floors / and perform other humble domestic tasks.","menial 也可作名词，指做杂役或卑微工作的雇员。","雇员承担搬煤和清洁等家务杂活。")],M("The scientist described routine glass washing as highly prestigious executive work requiring advanced legal training and independent authority.","The scientist described routine glass washing as menial work, while recognising that it was necessary for the experiment.","单调低技能的清洗工作不属于高地位的专业管理工作。"),[Q("Menial work is often?","low-status and routine","highly prestigious and autonomous","a written agreement between firms","menial.s1 描写低地位、重复的工作。"),Q("In the household example, menials are?","workers doing humble domestic tasks","people receiving a memorial award","members elected to parliament","menial.s2 可作名词指做杂役的人。"),Q("Why did the assistant wash the glassware carefully?","clean equipment was needed for the experiment","washing was the most prestigious legal profession","the task was a computer menu","实验需要洁净器皿。"),Q("Which use is a noun?","The menials carried coal and swept the hall.","She completed a menial task.","The job seemed menially repetitive.","menials 在此指从事杂役的人。","grammar")]);
P("menstruation","Menstruation comes from Latin menstruare, “to menstruate,” from menstruus, “monthly,” ultimately related to mensis, “month.”",C("menstruation.s1","生理健康","The nurse explained that menstruation is a normal part of the reproductive cycle and answered the student’s questions in private.","护士解释说月经是生殖周期的正常组成部分，并私下回答了学生的问题。","The nurse explained / that menstruation is a normal part / of the reproductive cycle / and answered the student’s questions in private.","menstruation 指月经或行经，是生理健康术语。","护士说明其属于正常生理周期。"),M("The leaflet defined menstruation as the monthly blood flow, then claimed that it is a kind of computer storage.","The leaflet defined menstruation as the monthly blood flow that is part of the reproductive cycle.","计算机存储与月经这一生理过程无关。"),[Q("Menstruation is part of the?","reproductive cycle","computer memory system","restaurant service","menstruation 指月经这一生理过程。"),Q("What did the nurse do?","answered the student’s questions privately","asked the student to memorize a menu","repaired the student’s jacket","护士私下回答了学生的问题。"),Q("Which field commonly uses menstruation?","reproductive health","commercial shipping","music criticism","该词属于生殖健康领域。"),Q("Which phrase is appropriate in health education?","the menstrual cycle and menstruation","menstruation of a company merger","menstruation the damaged pocket","menstruation 用于描述相关生理过程。","register")]);
P("mental","Mental comes from Latin mentalis, “of the mind,” from mens, “mind”; it can relate to thought or to intellectual activity.",[C("mental.s1","心理状态","The sudden move placed mental strain on the children, who missed their friends and needed time to settle into a new school.","突然搬家给孩子们造成了心理压力；他们想念朋友，也需要时间适应新学校。","The sudden move placed mental strain / on the children / who missed their friends / and needed time to settle into a new school.","mental.s1 指与人的心理、思想或精神状态有关。","思念和适应压力涉及心理状态。"),C("mental.s2","脑力活动","Solving the word puzzle was a mental exercise that required the team to compare clues and hold several possibilities in mind.","解这个文字谜题是一种脑力练习，需要团队比较线索并同时记住几种可能答案。","Solving the word puzzle / was a mental exercise / that required the team / to compare clues and hold several possibilities in mind.","mental.s2 可表示在头脑中进行的智力活动。","比较线索和记住可能答案需要思考。")],M("The puzzle was a mental exercise that required no thought, attention, memory, or other activity of the mind.","The puzzle was a mental exercise because solving it required thought, attention, and memory.","完全不需要思考或记忆的活动不属于脑力练习。"),[Q("Mental strain concerns a person’s?","mind and emotional state","physical height only","restaurant choices","mental.s1 与心理状态有关。"),Q("A mental exercise is an activity that uses?","thought and reasoning","only physical strength","a memorial monument","mental.s2 指头脑中的脑力活动。"),Q("Why was the puzzle a mental exercise?","it required comparing clues and remembering possibilities","it required repairing a pocket","it listed meals for a café","解题需要分析线索与记住选项。"),Q("Which phrase refers to psychological well-being?","mental health","mental menu","mental meridian","mental health 指心理健康。","collocation")]);
P("mental health","Mental health combines mental and health to describe psychological and emotional well-being, including how a person thinks, feels, and copes.",C("mental health.s1","校园支持","The school counsellor created a quiet drop-in hour where students could discuss stress and ask for support with their mental health.","学校辅导员安排了一个安静的开放时段，让学生讨论压力并寻求心理健康方面的支持。","The school counsellor created / a quiet drop-in hour / where students could discuss stress / and ask for support with their mental health.","mental health 指心理和情绪方面的健康状况。","学生可讨论压力并获得心理支持。"),M("The counsellor said mental health concerns only physical injuries and has nothing to do with feelings, thinking, or coping with stress.","The counsellor explained that mental health includes emotional well-being and the ability to cope with stress.","心理健康涉及情绪和应对压力，而非仅指身体受伤。"),[Q("Mental health concerns a person’s?","psychological and emotional well-being","ability to repair furniture","list of available meals","mental health 指心理和情绪健康。"),Q("What did the counsellor offer students?","a quiet time to discuss stress and seek support","a requirement to hide every difficulty","a list of computer commands","辅导员提供了讨论压力和寻求支持的时间。"),Q("Which action can support mental health?","talking with a counsellor about ongoing stress","pretending stress never affects anyone","memorizing a restaurant menu","与辅导员谈压力可获得心理支持。"),Q("Which phrase is a common collocation?","mental health support","mental health memento","mental health meridian","mental health support 是常见搭配。","collocation")]);
P("mentality","Mentality came from French mentalité, based on mental, and means a characteristic way of thinking or approaching situations.",C("mentality.s1","团队态度","The new coach tried to change the team’s defeatist mentality by setting realistic goals and praising steady improvement.","新教练通过设定切实目标并肯定持续进步，努力改变球队消极认输的心态。","The new coach tried to change / the team’s defeatist mentality / by setting realistic goals / and praising steady improvement.","mentality 指个人或群体惯有的思维方式或态度。","球队原有的认输倾向是一种群体心态。"),M("The coach described the team’s mentality as defeatist even though every player expected to win and approached setbacks with confidence.","The coach described the team’s mentality as defeatist because players expected failure before matches began.","始终自信期待获胜，不符合消极认输的心态。"),[Q("A defeatist mentality is a?","habitual way of thinking that expects failure","computer part that stores data","written agreement between groups","mentality 指思维方式或心态。"),Q("How did the coach try to change the team?","by setting goals and recognising progress","by removing every goal and discouraging effort","by giving them a restaurant menu","设定目标并认可进步有助改变球队心态。"),Q("Which word is closest to mentality?","mindset","memorial","merchandise","mindset 与 mentality 一样可指心态。"),Q("Which phrase is natural?","a practical mentality","a mentality of to practical","a practical mentalities it","mentality 可由形容词 practical 修饰。","grammar")]);
P("mentally","Mentally is formed from mental plus the adverb suffix -ly and means intellectually, psychologically, or in the mind.",C("mentally.s1","注意与思考","Although the route looked simple, the climber was mentally exhausted after hours of planning each move and watching the weather.","尽管路线看起来简单，攀登者在数小时规划每一步并观察天气后已精疲力竭。","Although the route looked simple / the climber was mentally exhausted / after hours of planning each move / and watching the weather.","mentally 修饰形容词 exhausted，说明疲惫发生在精神或认知层面。","长时间规划与判断使攀登者脑力疲劳。"),M("The climber was mentally exhausted, meaning only that his boots were wet while his concentration and thinking remained fully fresh.","The climber was mentally exhausted after sustained planning and decision-making.","此处 mentally exhausted 指精神和认知疲劳，并非靴子潮湿。"),[Q("Mentally exhausted means tired?","in the mind or psychologically","only in the legs","because of a torn jacket","mentally 表示在精神或心理层面。"),Q("What demanded sustained thought from the climber?","planning each move and monitoring the weather","memorizing a restaurant’s prices","repairing another climber’s boots","规划路线和观察天气需要持续思考。"),Q("Mentally is formed from mental plus?","-ly","-less","-ment","mentally 由 mental 加副词后缀 -ly 构成。","word-formation"),Q("Which sentence uses mentally naturally?","She mentally reviewed the steps before the exam.","She mentaled reviewed the steps before the exam.","She mentally review the steps yesterday.","mentally 可修饰动词 reviewed。","grammar")]);
P("mention","Mention came through Old French from Latin mentionem, “a calling to mind”; as a verb it means to refer to something briefly, and as a noun a brief reference.",[C("mention.s1","交谈提及","During the interview, the candidate mentioned her volunteer work but spent most of the time describing her engineering projects.","面试中，候选人提到了志愿服务，但大部分时间都在介绍工程项目。","During the interview / the candidate mentioned her volunteer work / but spent most of the time / describing her engineering projects.","mention 作动词表示简短地说到某事。","她简略提到志愿服务，并未详细展开。"),C("mention.s2","报道提及","The report gave special mention to two junior researchers whose careful measurements improved the final results.","报告特别提到了两位初级研究员，他们细致的测量改善了最终结果。","The report gave special mention / to two junior researchers / whose careful measurements / improved the final results.","mention 作名词可指简短提及或简要表扬。","报告用 special mention 对研究员作了特别表扬。")],M("The interviewer said she mentioned her volunteer work at length, although she referred to it only once in a single brief sentence.","The interviewer said she mentioned her volunteer work briefly before discussing her engineering projects.","仅一句简短说及不能称为详细介绍。"),[Q("To mention volunteer work is to?","refer to it briefly","write a complete memoir about it","repair the equipment used for it","mention 表示简短提及。"),Q("A special mention in a report is?","a brief reference or recognition","a full-length biography","a computer storage device","mention.s2 可作名词指简要提及或表扬。"),Q("What did the candidate discuss at greater length?","her engineering projects","the report’s junior researchers","the interview room menu","她主要介绍工程项目。"),Q("Which construction is standard?","mention a concern to the manager","mention about a concern to the manager","mention the manager about a concern","mention 后可直接接提及的内容。","grammar")]);
P("mentor","Mentor is named after Mentor in Homer’s Odyssey, adviser to Telemachus; the noun means an experienced guide, and the verb means to guide someone.",[C("mentor.s1","职业指导","An experienced editor became Jun’s mentor, reviewing his drafts and helping him plan a path into science journalism.","一位有经验的编辑成了俊的导师，审阅他的草稿，并帮助他规划进入科学新闻行业的道路。","An experienced editor became Jun’s mentor / reviewing his drafts / and helping him plan / a path into science journalism.","mentor 作名词指提供建议和帮助的有经验者。","编辑用经验指导俊的写作与职业规划。"),C("mentor.s2","指导新人","The senior engineer agreed to mentor two graduates during their first year, meeting them monthly to discuss design problems.","资深工程师同意在两名毕业生的第一年担任他们的导师，每月与他们讨论设计问题。","The senior engineer agreed / to mentor two graduates / during their first year / meeting them monthly to discuss design problems.","mentor 作动词表示指导经验较少的人。","工程师定期指导毕业生处理设计问题。")],M("The senior engineer mentored the graduates by refusing to answer questions, offer feedback, or share any experience with them.","The senior engineer mentored the graduates by discussing their designs and sharing practical advice.","拒绝提供建议或反馈不符合指导新人的意思。"),[Q("A mentor is usually?","an experienced guide who gives advice","a person who buys and sells goods","a written note about a meeting","mentor.s1 指经验丰富的指导者。"),Q("To mentor new graduates is to?","guide and support them as they learn","sell them commercial merchandise","ask them to memorize a poem","mentor.s2 作动词表示指导新人。"),Q("What did Jun’s mentor help him plan?","a path into science journalism","a route to a meridian","a recipe for a menu","编辑帮助俊规划职业道路。"),Q("Which phrase is natural?","mentor a junior colleague","mentor to a junior colleague","mentor with a junior colleague advice","mentor 作动词时可直接接受指导者。","grammar")]);
P("menu","Menu came through French menu, “small, detailed,” from Latin minutus; it first meant a detailed list of dishes and later a list of computer options.",[C("menu.s1","餐馆点餐","The waiter brought a menu with seasonal dishes, then explained which soups could be made without dairy.","服务员拿来一份列有时令菜肴的菜单，随后说明哪些汤可以做成不含乳制品。","The waiter brought a menu / with seasonal dishes / then explained / which soups could be made without dairy.","menu 作名词指餐馆提供的可选菜品清单。","菜单列出菜品，方便顾客选择。"),C("menu.s2","软件操作","Choose “Export” from the file menu to save a copy of the finished chart as a PDF.","从文件菜单中选择“导出”，即可把完成的图表另存为 PDF。","Choose “Export” / from the file menu / to save a copy / of the finished chart as a PDF.","计算机 menu 指屏幕上显示的一组选项。","用户从程序选项中选取导出功能。")],M("The waiter called the restaurant’s menu a list of computer commands displayed on a screen, not a list of dishes.","The waiter handed the diners a restaurant menu listing the dishes available that evening.","餐馆菜品清单与屏幕上的软件选项是不同义项。"),[Q("A restaurant menu lists?","dishes available to order","the restaurant’s computer passwords","longitude lines on a map","menu.s1 是餐馆菜品清单。"),Q("A file menu on a computer shows?","commands or choices available in the program","the café’s soup ingredients only","a list of people’s memories","menu.s2 指软件提供的屏幕选项。"),Q("Which choice lets the user save a PDF copy?","Export","Memorial","Meridian","例句要求选择 Export 导出图表。"),Q("Which phrase is natural in software instructions?","select an option from the file menu","select an option to the file menu","file menu an option from select","常用结构为 select an option from a menu。","collocation")]);
P("mercantile","Mercantile came through French and Italian from Latin mercantilis, based on mercari, “to trade”; it describes trade or commerce.",[C("mercantile.s1","商业街区","The old town’s mercantile quarter grew around the harbour, where merchants stored imported cloth and arranged deliveries.","老城的商业区围绕港口发展，商人们在那里储存进口布料并安排交货。","The old town’s mercantile quarter grew / around the harbour / where merchants stored imported cloth / and arranged deliveries.","mercantile 表示与商人、贸易或商业有关。","港口仓储和交货构成商业活动。"),C("mercantile.s2","经济思想","The lecturer explained that mercantile theory treated trade surpluses and state control of commerce as sources of national wealth.","讲师解释说，重商主义理论把贸易顺差和国家对商业的控制视为国家财富来源。","The lecturer explained / that mercantile theory treated trade surpluses / and state control of commerce / as sources of national wealth.","历史经济语境中 mercantile 可指与重商主义有关。","例句描述重商主义的贸易与国家控制观点。")],M("The museum described the harbour’s mercantile quarter as a farming settlement with no buying, selling, shipping, or trade.","The museum described the harbour’s mercantile quarter as a commercial district where merchants stored and traded goods.","没有买卖或贸易活动的地方不符合 mercantile 的商业义。"),[Q("A mercantile district is connected with?","trade and commerce","mental exercise","memorial ceremonies","mercantile.s1 表示商业或贸易相关的。"),Q("Mercantile theory in the example links wealth with?","trade surpluses and state control of commerce","the number of mermaids in the sea","computer memory capacity","例句说明重商主义与贸易顺差及国家控制有关。"),Q("Where did the old town’s trade centre grow?","around the harbour","inside a cell membrane","at the school counselling office","港口仓储和交货带动了商业区。"),Q("Which phrase is natural?","mercantile activity","mercantile of activity","activity mercantiling","mercantile 可修饰名词 activity。","grammar")]);
P("mercenary","Mercenary came through Old French from Latin mercenarius, “working for pay,” from merces, “wages”; it can describe profit-driven motives or a paid soldier.",[C("mercenary.s1","动机评价","The reviewer called the consultant’s advice mercenary because every recommendation seemed designed to increase his fee rather than help the client.","评论者称这位顾问的建议唯利是图，因为每条建议似乎都是为了增加报酬，而非帮助客户。","The reviewer called / the consultant’s advice mercenary / because every recommendation seemed designed / to increase his fee rather than help the client.","mercenary 作形容词可批评只看重金钱利益的动机。","顾问的建议以增加个人报酬为先。"),C("mercenary.s2","军事历史","The commander recruited mercenaries from abroad, paying them to fight in a conflict that did not involve their own country.","指挥官从国外招募雇佣兵，付钱让他们参加与其本国无关的冲突。","The commander recruited / mercenaries from abroad / paying them to fight / in a conflict that did not involve their own country.","mercenary 作名词可指为报酬而参战的职业士兵。","士兵受雇作战，且来自冲突双方以外的国家。")],M("The commander called the soldiers mercenaries even though they received no pay and had volunteered only to defend their own home village.","The commander called the foreign soldiers mercenaries because they were paid to fight in another country’s conflict.","无报酬且保卫本地的志愿者不符合雇佣兵的定义。"),[Q("A mercenary adviser is criticised for?","putting financial gain ahead of principle","giving free help without any reward","remembering a childhood event","mercenary.s1 表示唯利是图的。"),Q("A mercenary soldier fights mainly because?","the soldier is paid to do so","the soldier is repairing a uniform","the soldier is writing a memoir","mercenary.s2 指受雇作战的士兵。"),Q("Where were the recruited soldiers from?","abroad","the commander’s own village","a computer menu","例句说指挥官从国外招募士兵。"),Q("Which phrase uses mercenary as a noun?","The mercenaries crossed the border.","His motives seemed mercenary.","The mercenary motive was clear.","The mercenaries 作复数名词，指雇佣兵。","grammar")]);
P("merchandise","Merchandise came through Anglo-French and Old French from words for a merchant’s goods or trade; it means goods for sale and can also mean to promote and sell them.",[C("merchandise.s1","商店货品","The museum shop arranged its merchandise by theme, keeping maps, postcards, and locally made ceramics on separate shelves.","博物馆商店按主题陈列商品，把地图、明信片和本地陶器分开放在不同货架上。","The museum shop arranged / its merchandise by theme / keeping maps, postcards, and locally made ceramics / on separate shelves.","merchandise 作名词指买卖的商品或货品。","商店按类别陈列待售物品。"),C("merchandise.s2","产品推广","The studio licensed a company to merchandise its characters through school bags, toys, and other products.","工作室授权一家公司通过书包、玩具等产品推广其角色。","The studio licensed a company / to merchandise its characters / through school bags, toys / and other products.","merchandise 作动词表示推销或销售商品。","公司把角色用于产品并推广销售。")],M("The museum called the maps and ceramics merchandise even though the shop did not offer them for sale or trade.","The museum shop called its saleable maps and ceramics merchandise and displayed them for visitors to buy.","merchandise 指出售或交易的商品，非出售的展品不一定符合此义。"),[Q("Merchandise in a shop means?","goods available for sale","a written office reminder","the shop’s computer storage","merchandise.s1 指可供买卖的货品。"),Q("To merchandise a character is to?","promote and sell products featuring it","write a personal memoir about it","repair the character’s broken cell membrane","merchandise.s2 作动词表示推广销售相关产品。"),Q("Which items appeared in the museum shop?","maps, postcards, and local ceramics","hired soldiers and uniforms","restaurant soups and desserts","商店货架上有地图、明信片和陶器。"),Q("Which sentence uses merchandise as a verb?","The firm merchandises the artist’s designs on bags.","The firm displayed its merchandise near the door.","The merchandise arrived in three boxes.","merchandises 是动词形式，表示推销设计产品。","grammar")]);
P("merchant","Merchant came through Anglo-French from Vulgar Latin mercatantem, a buyer or trader, from Latin mercari, “to trade”; it can be a trade-related adjective as well as a trader noun.",[C("merchant.s1","港口贸易","The grain merchant negotiated with farmers in three counties and shipped the harvest to bakeries along the coast.","这位谷物商人与三个郡的农户谈妥交易，并把收获的谷物运往沿海面包店。","The grain merchant negotiated / with farmers in three counties / and shipped the harvest / to bakeries along the coast.","merchant 作名词指以买卖商品为业的人。","谷物商人采购并转售收获的粮食。"),C("merchant.s2","商业航运","The museum displayed a merchant vessel built to carry textiles and spices between ports rather than to fight naval battles.","博物馆展出了一艘商船，它用于在港口间运输纺织品和香料，而非参加海战。","The museum displayed / a merchant vessel / built to carry textiles and spices / between ports rather than to fight naval battles.","merchant 可作形容词，表示与贸易或商人有关。","merchant vessel 指从事商业运输的船只。")],M("The grain merchant gave the harvest away for free and never bought, sold, or traded any goods.","The grain merchant bought crops from local farmers and sold them to bakeries for a profit.","从不参与买卖的人不符合商人的职业定义。"),[Q("A grain merchant is someone who?","buys and sells grain","repairs grain sacks without trading","writes reports about computer memory","merchant.s1 指从事商品买卖的商人。"),Q("A merchant vessel is designed for?","commercial transport between ports","a memorial ceremony at sea","storing computer files","merchant.s2 指商业运输相关的。"),Q("What did the merchant ship to bakeries?","the harvested grain","menus from the museum","mercury from a laboratory","谷物商人把收获的粮食运给面包店。"),Q("Which phrase uses merchant as an adjective?","a merchant fleet carrying cargo","a merchant who sells grain","the merchant negotiated a price","merchant fleet 中 merchant 修饰 fleet。","grammar")]);
P("merciful","Merciful combines mercy with the suffix -ful and means showing kindness or leniency toward someone who could be punished or harmed.",C("merciful.s1","宽大处置","The judge was merciful to the first-time offender, choosing community service after considering the harm and the sincere apology.","法官对初犯从宽处理，在考虑其造成的伤害和诚恳道歉后，判处社区服务。","The judge was merciful / to the first-time offender / choosing community service / after considering the harm and the sincere apology.","merciful 表示表现出仁慈、宽恕或宽大。","法官考虑到道歉与情节后从宽判决。"),M("The judge was merciful because she imposed the harshest possible punishment and refused to consider any apology or circumstances.","The judge was merciful because she chose a lenient sentence after weighing the apology and circumstances.","不考虑情节并施以最严厉惩罚并非宽大处理。"),[Q("A merciful judge is likely to show?","kindness or leniency","a desire for revenge without limit","a list of goods for sale","merciful 表示仁慈或宽大。"),Q("What sentence did the judge choose?","community service","the harshest available penalty","a job as a merchant","法官判处社区服务而非最重刑罚。"),Q("Which word is closest to merciful?","compassionate","merciless","menacing","compassionate 表示富有同情心。"),Q("Merciful is formed from mercy plus?","-ful","-less","-ly","merciful 由 mercy 加 -ful 构成。","word-formation")]);
P("merciless","Merciless combines mercy with -less, meaning “without”; it describes someone or something showing no pity or compassion.",C("merciless.s1","严酷环境","The hikers faced a merciless wind on the exposed ridge, with no shelter until they reached the lower valley.","徒步者在无遮蔽的山脊上遭遇刺骨的狂风，直到抵达低处山谷才找到避风处。","The hikers faced / a merciless wind / on the exposed ridge / with no shelter until they reached the lower valley.","merciless 可形容冷酷无情的人，也可形容毫不留情的环境或条件。","狂风持续猛烈且没有遮蔽，体现严酷无情。"),M("The merciless wind was gentle and quickly stopped whenever the hikers felt cold, giving them full shelter on the ridge.","The merciless wind kept blowing across the exposed ridge and offered the hikers no relief.","温和且及时停止的风不符合 merciless 所表达的毫不留情。"),[Q("A merciless person shows?","no pity or compassion","kindness to someone in trouble","careful guidance as a mentor","merciless 表示不讲情面、没有怜悯。"),Q("How did the wind affect the hikers?","it kept blowing on an exposed ridge without shelter","it stopped whenever they felt cold","it carried them safely to the valley","山脊上的风强劲且没有避风处。"),Q("Which word is the opposite of merciless?","merciful","menacing","menial","merciful 与 merciless 意义相反。","distinction"),Q("Which phrase is natural?","a merciless winter","a mercyless winter","a winter mercilessly of","正确拼写是 merciless。","spelling")]);
P("mercury","The element name came through Medieval Latin mercurius from Latin Mercurius, the Roman god; its mobility likely linked it to the planet Mercury, while Hg comes from Greek hydrargyros, “liquid silver.”",[C("mercury.s1","化学实验","The technician wore gloves while transferring mercury from a damaged thermometer into a sealed container for hazardous-waste collection.","技术员戴着手套，把破损温度计中的汞转移到密封容器里，以便作为危险废物收集。","The technician wore gloves / while transferring mercury / from a damaged thermometer / into a sealed container for hazardous-waste collection.","mercury.s1 指常温下呈液态的银白色金属汞。","温度计中的液态金属被收集处理。"),C("mercury.s2","行星观测","Mercury appeared low above the horizon shortly after sunset, visible for only a brief period before the sky became dark.","日落后不久，水星出现在地平线附近，只能在天色变暗前短暂看见。","Mercury appeared low / above the horizon / shortly after sunset / visible for only a brief period.","Mercury.s2 是离太阳最近的行星水星，名称首字母大写。","例句描述日落后可见的行星。")],M("The laboratory labelled the liquid metal mercury, although it was a lightweight gas that remained invisible in the sealed container.","The laboratory labelled the liquid silver-white metal mercury and sealed it for hazardous-waste collection.","汞是常温下呈液态的金属，不是轻质气体。"),[Q("At ordinary room temperature, mercury is a?","liquid silver-white metal","mythical sea creature","list of available computer choices","mercury.s1 指常温下呈液态的银白色金属。"),Q("Mercury in the sky is?","the planet closest to the Sun","the metal inside a thermometer","the Roman word for a menu","mercury.s2 指离太阳最近的行星。"),Q("When could the planet be seen in the example?","briefly after sunset","at midnight beneath the sea","only inside a laboratory","例句说水星在日落后短暂可见。","context"),Q("What is the chemical symbol Hg associated with?","the Greek word for liquid silver","the Latin word for mermaid","the name of a computer menu","Hg 源自表示液态银的希腊词。","word-formation")]);
P("mercy","Mercy came through Old French merci from Latin mercedem, originally “reward or wages,” and developed senses including compassion, forgiveness, and relief from something worse.",[C("mercy.s1","宽恕与同情","The injured fox was at the mercy of the rescue team, who handled it gently and treated the wound before releasing it.","受伤的狐狸只能任由救援队处置；队员们轻柔地对待它，处理伤口后将它放归自然。","The injured fox was / at the mercy of the rescue team / who handled it gently / and treated the wound before releasing it.","mercy.s1 指对可能受伤害或惩罚者表现出的怜悯、善意或宽恕。","救援人员善待并治疗了受伤的狐狸。"),C("mercy.s2","幸运转机","The rain was a mercy after weeks of drought, arriving just before the reservoir reached its lowest recorded level.","干旱持续数周后，这场雨真是及时的恩惠，在水库降到有记录以来最低水位前赶到。","The rain was a mercy / after weeks of drought / arriving just before / the reservoir reached its lowest recorded level.","mercy.s2 可指阻止更坏情况发生的幸运或恩惠。","及时降雨缓解了严重干旱。")],M("The rescue team showed mercy to the injured fox by ignoring its wound and leaving it trapped without food or water.","The rescue team showed mercy by treating the injured fox gently and caring for its wound.","漠视伤口并弃之不顾不体现怜悯或善待。"),[Q("To show mercy is to show?","compassion or leniency","a desire to cause needless suffering","a list of products for sale","mercy.s1 指怜悯、宽恕或善意。"),Q("The rain was a mercy because it?","arrived in time to ease the drought","made the drought more severe","was listed on a restaurant menu","mercy.s2 可指避免更坏结果的恩惠。"),Q("How did the rescue team treat the fox?","gently and with care","they ignored the injury","they hired it as a mercenary","救援人员善待狐狸并处理伤口。"),Q("Which phrase uses mercy to mean compassion?","The judge showed mercy to the offender.","The judge showed menace to the offender.","The judge showed merchandise to the offender.","mercy 表示对可能受罚者的怜悯或宽恕。")]);
P("mere","Mere came through Old French mier from Latin merus, “unmixed or pure”; the limiting sense “nothing more than” developed later.",[C("mere.s1","数量限制","The repair took a mere ten minutes, far less time than the team had expected when they saw the damaged hinge.","修理只花了十分钟，比团队看到损坏的铰链时预想的时间短得多。","The repair took / a mere ten minutes / far less time / than the team had expected.","mere.s1 作限定词，强调数量或程度很小、仅仅如此。","十分钟比预期时间少得多，突出数量有限。"),C("mere.s2","纯粹事实","Her presence was a mere formality because the committee had already reached its decision before the hearing began.","她的出席纯粹只是走个形式，因为听证会开始前委员会就已作出决定。","Her presence was / a mere formality / because the committee had already reached its decision / before the hearing began.","mere.s2 可表示某事纯粹是所说的那种情况，没有更深含义。","委员会已定案，因此她的出席只是形式。")],M("The repair took a mere ten minutes, meaning it lasted several days and was far longer than anyone expected.","The repair took a mere ten minutes, meaning it took only a short amount of time.","mere 在此表示仅仅十分钟，和持续数天的说法矛盾。"),[Q("A mere ten minutes means?","only ten minutes","at least ten hours","a written note lasting ten minutes","mere.s1 强调时间很短、仅仅十分钟。"),Q("A mere formality is something that is?","only a form or procedure, with little real effect","the most important decision itself","a fully unexpected change","mere.s2 表示纯粹形式上的事情。"),Q("Why was the hearing only a formality?","the committee had already made its decision","the committee had not yet met","the chair had forgotten the agenda","听证开始前委员会已经决定。"),Q("Which phrase uses mere correctly?","It was a mere suggestion, not a final plan.","It mere was a suggestion, not a final plan.","It was merely suggestion, not a final plan.","mere 是放在名词 suggestion 前的限定词。","grammar")]);
P("merely","Merely is formed from mere plus the adverb suffix -ly and means only or just, without anything more.",C("merely.s1","澄清事实","I was merely asking whether the figures had been checked; I was not accusing anyone of changing them.","我只是在问这些数字是否核对过，并没有指责任何人篡改数据。","I was merely asking / whether the figures had been checked / I was not accusing anyone / of changing them.","merely 修饰动词或短语，表示只是、仅仅。","说话者澄清自己只是询问，并未指控。"),M("She said she was merely asking about the figures, but then admitted that she had formally accused a colleague of falsifying them.","She said she was merely asking about the figures and had made no accusation.","正式指控与“只是询问”的澄清不一致。"),[Q("Merely means?","only or just","in a threatening manner","with great compassion","merely 表示仅仅、只是。"),Q("What was the speaker doing?","asking whether the figures had been checked","accusing a colleague of falsification","rewriting the company’s menu","说话者只是询问数字是否核对。"),Q("Merely is formed from mere plus?","-ly","-ful","-less","merely 由 mere 加副词后缀 -ly 构成。","word-formation"),Q("Which sentence uses merely naturally?","The delay was merely an hour.","The delay merely of an hour.","The merely delay lasted.","merely 可修饰名词短语前的数量表达。","grammar")]);
P("merge","Merge came from Latin mergere, “to dip or sink”; its modern senses include combining things into one or becoming indistinguishable from something else.",[C("merge.s1","组织整合","The two charities agreed to merge their offices and fundraising teams so that more donations could support local clinics.","两家慈善机构同意合并办公室和筹款团队，以便让更多捐款支持当地诊所。","The two charities agreed / to merge their offices and fundraising teams / so that more donations / could support local clinics.","merge.s1 作动词表示把两个组织、部分或事物合为一体。","两家机构整合团队和办公室。"),C("merge.s2","颜色融合","At dusk, the hills on the horizon seemed to merge with the darkening sky until their outlines were hard to distinguish.","黄昏时，地平线上的群山似乎渐渐融入暗下来的天空，轮廓难以分辨。","At dusk / the hills on the horizon seemed to merge / with the darkening sky / until their outlines were hard to distinguish.","merge.s2 可指边界逐渐消失、难以分辨地融合。","群山轮廓与天空逐渐难以区分。")],M("The two charities announced a merger, but they kept entirely separate offices, teams, finances, and management with no combination at all.","The two charities merged their offices and teams into one organisation with shared management.","保持完全独立、没有整合，不符合 merge 的合并义。"),[Q("When two charities merge, they?","combine into one organisation","become two unrelated groups","memorize one another’s names","merge.s1 表示合并为一体。"),Q("Hills merge with the sky means?","their outlines gradually become difficult to distinguish","they form a new charity","they become brighter than noon","merge.s2 表示逐渐融合、界限变模糊。"),Q("Why did the charities combine teams?","to direct more donations to local clinics","to make the hills change colour","to write a memorandum for a different charity","合并团队旨在将更多捐款用于诊所。"),Q("Which phrase uses merge naturally?","merge two departments into one","merge two departments with one","merge two departments from one into","merge A into B 是自然搭配。","collocation")]);
P("merger","Merger comes from merge; the noun first developed in legal use for absorption and later broadened to any act of combining.",C("merger.s1","企业整合","The proposed merger would bring the two regional bus companies under one management while keeping their existing routes for the first year.","拟议中的合并将把两家地区公交公司纳入统一管理，同时在第一年保留现有线路。","The proposed merger / would bring the two regional bus companies / under one management / while keeping their existing routes for the first year.","merger 是两个公司或组织合并为一个的行为或结果。","两家公司纳入统一管理，体现组织合并。"),M("The announced merger left both companies under completely separate management with no shared operations or ownership.","The announced merger placed both companies under one management and combined their operations.","完全保持分离，没有形成合并。"),[Q("A company merger is?","the joining of companies into one","a brief company memo","a hired soldier","merger 指公司或组织的合并。"),Q("What would happen to the bus companies?","they would share one management","they would end all existing routes immediately","they would become two separate countries","方案将两家公司纳入统一管理。"),Q("Why keep the routes at first?","to maintain existing service during the transition","to prevent the companies from merging at all","to turn the routes into meridians","例句说第一年保留原有线路。"),Q("Which phrase is standard?","a merger between two firms","a merger among of two firms","two firms mergering","merger between two firms 是自然搭配。","collocation")]);
P("meridian","Meridian came through Old French from Latin meridianus, “of midday,” from meridies, formed from medius, “middle,” and dies, “day”; it names a line passing through the poles.",C("meridian.s1","地图定位","The cartographer used the prime meridian as the reference line for measuring longitude on the world map.","制图师把本初子午线作为在世界地图上测量经度的基准线。","The cartographer used / the prime meridian / as the reference line / for measuring longitude on the world map.","meridian 指连接两极、用于测量经度的假想线。","本初子午线用于经度测量。"),M("The cartographer labelled a horizontal line running around the equator a meridian, although it did not pass through either pole.","The cartographer labelled a north-south line passing through both poles a meridian.","子午线连接南北两极；赤道是纬线。"),[Q("A meridian on a globe is a line that?","passes through the poles","circles the equator from east to west","marks the menu of a computer","meridian 指经过两极的经线。"),Q("What does the prime meridian help measure?","longitude","temperature of mercury","the height of a mountain","本初子午线是测量经度的基准。"),Q("Which direction does a meridian generally run?","north to south","east to west around the equator","upward from a valley only","经线连接南北方向。"),Q("Which phrase is natural?","the Greenwich meridian","the Greenwich memento","the Greenwich merchandise","Greenwich meridian 是常见地理名称。","collocation")]);
P("merit","Merit came through Old French from Latin meritum, “service, worth, or value,” from mereri, “to earn or deserve”; as a verb, it means deserve.",[C("merit.s1","作品优点","The report’s main merit was its clear comparison of costs, risks, and long-term benefits for each option.","这份报告的主要优点是清楚比较了每个方案的成本、风险和长期收益。","The report’s main merit / was its clear comparison / of costs, risks, and long-term benefits / for each option.","merit.s1 作名词指值得肯定的优点或价值。","报告的清晰比较是其优点。"),C("merit.s2","值得考虑","The unusual proposal merits further study because it could reduce waste without raising the project’s overall cost.","这个不同寻常的提议值得进一步研究，因为它可能在不增加项目总成本的情况下减少浪费。","The unusual proposal merits further study / because it could reduce waste / without raising / the project’s overall cost.","merit.s2 作动词表示值得获得关注、考虑或处理。","提案有潜在收益，因此值得研究。")],M("The proposal merited serious review, but the committee said it deserved no attention and rejected it without reading it.","The proposal merited serious review because its potential savings deserved careful consideration.","merit 作动词意为值得；既然提案值得审查，就不应说完全不值得关注。"),[Q("The main merit of a report is its?","good feature or value","unavoidable danger","list of computer commands","merit.s1 指值得肯定的优点。"),Q("A proposal merits further study means it?","deserves more study","has already been rejected as worthless","is a commercial merchant","merit.s2 作动词表示值得进一步研究。"),Q("Why did the proposal merit further study?","it might reduce waste without increasing cost","it was only a restaurant menu","it contained no information at all","提案有减少浪费且不增成本的潜力。"),Q("Which sentence uses merit as a noun?","The plan has several merits.","The plan merits a review.","The plan is meriting to review yesterday.","merits 在此是名词复数，指优点。","grammar")]);
P("meriting","Meriting is the present participle of merit and describes something that deserves attention, consideration, or a particular response.",C("meriting.s1","研究评价","The archive contains several letters meriting closer study because they reveal how the town organised relief after the fire.","档案中有几封值得深入研究的信件，因为它们揭示了火灾后该镇如何组织救济。","The archive contains / several letters meriting closer study / because they reveal / how the town organised relief after the fire.","meriting 作现在分词，修饰 letters，表示这些信件值得研究。","信件揭示了重要历史信息，因此值得深入研究。"),M("The archive described the letters as meriting closer study, then explained that they contained no relevant information and deserved no attention.","The archive described the letters as meriting closer study because they contain useful evidence about the town’s relief work.","值得深入研究应当有理由支持，不能同时说材料毫无相关价值。"),[Q("Letters meriting closer study are letters that?","deserve more careful examination","must never be read again","are already a company merger","meriting 表示值得获得进一步关注。"),Q("What do the letters reveal?","how the town organised relief after a fire","how to identify a meridian","how to repair a torn pocket","信件揭示火灾后的救济组织方式。"),Q("Meriting is the present participle of?","merit","mercy","mermaid","meriting 是动词 merit 的现在分词。","word-formation"),Q("Which phrase is natural?","an issue meriting careful attention","an issue meriting to careful attention","an issue meriting of careful attention","meriting 可直接接名词短语作宾语。","grammar")]);
P("mermaid","Mermaid is a Middle English compound of mere, “sea,” and maid, literally “maid of the sea.”",C("mermaid.s1","民间传说","In the folktale, a mermaid watched the fishing boats from a rock and sang whenever the moon rose over the bay.","民间故事中，一位美人鱼在岩石上注视渔船，每当月亮升上海湾时便会歌唱。","In the folktale / a mermaid watched the fishing boats / from a rock / and sang whenever the moon rose over the bay.","mermaid 是传说中上半身像女子、下半身像鱼的海中生物。","故事将美人鱼描绘为海湾中的神话生物。"),M("The storyteller called the sea creature a mermaid, then described it as an ordinary land mammal with four legs and no fish-like body.","The storyteller called the sea creature a mermaid and described its upper body as human and its lower body as fish-like.","四足陆生哺乳动物不符合美人鱼的传统形象。"),[Q("A mermaid is a mythical being with?","a human upper body and a fish-like lower body","the body of a hired soldier","the form of a computer menu","mermaid 指上半身像人、下半身像鱼的神话生物。"),Q("Where did the mermaid watch the boats?","from a rock by the bay","inside a company office","on a mountain meridian","故事说她坐在海湾边的岩石上。"),Q("What does the compound mermaid literally suggest?","a maid of the sea","a merchant of the moon","a memory from a river","该词由 sea 的旧词 mere 与 maid 组成。","word-formation"),Q("Which setting best suits a mermaid folktale?","a rocky coast under a rising moon","a spreadsheet menu in an office","a courtroom during a merger hearing","海岸与月夜是海中传说的自然背景。")]);

})();
